function clockLabel(){return new Date().toTimeString().slice(0,5);}
// 持续问题的唯一持有：同一问题重复出现只更新那一条，不堆叠。问题出现/解除独立于主线迁移。
let scenarioProblemId=null;
function upsertProblem(cfg){
  const existing=notifications.find(item=>item.id===cfg.id);
  if(existing){
    existing.deleted=false;existing.resolved=false;existing.read=false;existing.time=clockLabel();
    existing.kind=cfg.kind;existing.detail=cfg.detail;
  }else{
    notifications.unshift({id:cfg.id,kind:cfg.kind,cat:cfg.cat,title:cfg.title,detail:cfg.detail,
      time:clockLabel(),action:cfg.action,target:cfg.target,read:false,resolved:false,deleted:false,dedupe:cfg.id});
  }
}
function resolveProblem(id){
  const item=notifications.find(entry=>entry.id===id);
  if(item&&!item.resolved){item.read=true;item.resolved=true;item.resolvedAt=clockLabel();}
}
// 场景切换只同步“持续问题”，不按枚举机械地制造故障或稳定态 Toast（数据与状态 §5.8）。
function syncScenarioProblem(state){
  const p=(STATE_MODEL[state]||{}).problem||null;
  const nextId=p?p.id:null;
  if(scenarioProblemId&&scenarioProblemId!==nextId) resolveProblem(scenarioProblemId);
  if(p) upsertProblem(p);
  scenarioProblemId=nextId;
  renderNotifications();
}
// 兼容旧调用点：启停/重启已有任务卡与结果 Toast，这里不再叠加机械播报。
function suppressNextStateAnnounce(){ window.__suppressStateAnnounce=true; }
function announceStateTransition(prev,next){
  window.__suppressStateAnnounce=false;
  syncScenarioProblem(next);
}

