function installPathError(value){
  const v=(value||'').trim();
  if(!v) return '安装位置不能为空。';
  if(v==='~'||v==='~/') return '不要直接装在家目录根下，请指定一个子目录。';
  if(/^\/(System|usr|bin|sbin|etc|var|private|Library)(\/|$)/.test(v)) return '这是系统保护目录，拒绝写入；请换到用户目录或数据根内。';
  if(/^[A-Za-z]:\\?(Windows|Program Files)(\\|$)/i.test(v)) return '这是系统保护目录，拒绝写入；请换到用户目录或数据根外的数据盘。';
  return '';
}
function dropzoneBlock(){
  return `<div class="dropzone${installPick?(installPick.ok?' picked':' bad'):''}" id="dropzone">${dropzoneInnerHtml()}</div>
    <div class="dropzone-actions">
      <button class="btn ghost" data-prototype-action="drop-pick">选择文件…</button>
      <button class="btn ghost" data-prototype-action="drop-clear"${installPick?'':' disabled'}>清除</button>
    </div>`;
}
function proxyFlag(){
  const addr=installProxyAddr.trim();
  if(!addr) return '';
  return ` --proxy ${installProxyType==='socks5'?'socks5h':'http'}://${addr}`;
}
