  const entry=installPath===DEFAULT_MANAGED_PREFIX?MANAGED_ENTRY:installPath.trim().replace(/\/+$/,'').replace(/(\/runtime)?(\/opencodex)?$/,'')+'/bin/ocx';
  return `
    <div class="wiz-block">
      <span class="wiz-label">安装位置</span>
