    </div>

    <label class="wiz-ack"><input type="checkbox" id="installAck"${installAck?' checked':''}><span>我了解：会写入上面的位置${installMode==='net'?'并联网下载官方包':'并从离线包展开'}；不写系统目录与全局 npm 前缀；失败不改动现有运行来源。</span></label>

    <details class="wiz-more"><summary>说明 / 下载地址</summary>
      <p class="wiz-hint">安装等价于在目标目录建一个私有 npm 项目（<code>package.json</code> + <code>package-lock.json</code> + <code>node_modules</code>），装完把运行来源切到它；卸载只删这份包体，不碰 <code>~/.codex/config.toml</code> 与 <code>OPENCODEX_HOME</code>。</p>
      ${downloadListHtml()}
    </details>
  `;
}
function installProgressHtml(){
  const net=installMode==='net';
  const pct=Math.round(installProgress);
  const substeps=net
    ?[['解析并下载官方包','按 registry 拉取 '+OFFICIAL_TARBALL_NAME],['写入私有前缀并链接 bin','node_modules 与 runtime/bin/ocx'],['校验并切换运行来源','切换后重启才生效']]
    :[['校验离线包','比对文件名与包名是否为 '+PKG],['展开到私有前缀并链接 bin','node_modules 与 runtime/bin/ocx'],['校验并切换运行来源','切换后重启才生效']];
  return `<div class="wiz-progress">
    <div class="wiz-progress-head"><b>${installDone?'安装完成':'正在安装 OpenCodex'}</b><span>${net?'联网安装':'导入离线包'} · ${pct}%</span></div>
    <div class="wiz-progress-bar" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}" aria-label="安装进度"><div class="wiz-progress-fill${installDone?' done':''}" style="width:${pct}%"></div></div>
    ${net
      ?`<pre class="wiz-console wiz-console-fixed" id="installConsole" aria-label="命令行进度">${installLog.map(line=>`<span class="${line.cls||''}">${line.text}</span>`).join('\n')}</pre>`
      :`<ul class="wiz-substeps">${substeps.map(([title,desc],index)=>{
          const cls=installDone||index<installSubstep?'ok':(index===installSubstep?'on':'');
          return `<li class="${cls}"><span><b>${title}</b> · ${desc}</span></li>`;
        }).join('')}</ul>`}
    ${installDone?`<p class="wiz-done">运行来源已切到「托管安装」：<code>${installPath}</code>。原型只演示界面，不写盘、不联网。</p>`:''}
  </div>`;
}
function installBodyHtml(){
  return `<div class="wiz">${installStepsHtml()}${installRunning||installDone?installProgressHtml():installConfigHtml()}</div>`;
}
function syncInstallConfirm(){
  const err=installPathError(installPath);
  const needPick=installMode==='file'&&!(installPick&&installPick.ok);
  const ready=!err&&installAck&&!needPick;
  const btn=document.getElementById('modalConfirm');
  if(btn) btn.disabled=!ready;
  return ready;
}
function syncInstallButtons(){
  if(installDone){
    modalConfirm.textContent='完成';modalConfirm.disabled=false;
    modalCancel.textContent='关闭';modalCancel.disabled=false;
  }else if(installRunning){
    modalConfirm.textContent='安装中…';modalConfirm.disabled=true;
    modalCancel.textContent='取消安装';modalCancel.disabled=false;
  }else{
    modalConfirm.textContent='开始安装';modalCancel.textContent='取消';modalCancel.disabled=false;
    syncInstallConfirm();
  }
}
function renderInstallModal(){
  const host=document.getElementById('installHost');
  if(!host) return;
  host.innerHTML=installBodyHtml();
  wireDropzone();
  const pathInput=document.getElementById('installPathInput');
  if(pathInput){
    pathInput.addEventListener('input',()=>{installPath=pathInput.value;renderInstallModal();});
  }
  const verInput=document.getElementById('installVersionInput');
  if(verInput) verInput.addEventListener('input',()=>{installVersion=verInput.value;});
  const proxyType=document.getElementById('installProxyType');
  if(proxyType) proxyType.addEventListener('change',()=>{installProxyType=proxyType.value;renderInstallModal();});
  const proxyAddr=document.getElementById('installProxyAddr');
  if(proxyAddr) proxyAddr.addEventListener('input',()=>{installProxyAddr=proxyAddr.value;});
  const ack=document.getElementById('installAck');
  if(ack) ack.addEventListener('change',()=>{installAck=ack.checked;renderInstallModal();});
  document.querySelectorAll('input[name="installSrc"]').forEach(input=>{
    input.addEventListener('change',()=>{installMode=input.value==='file'?'file':'net';renderInstallModal();});
  });
  const consoleEl=document.getElementById('installConsole');
  if(consoleEl) consoleEl.scrollTop=consoleEl.scrollHeight;
  syncInstallButtons();
}
function stopInstallTimer(){
  if(installTimer){clearInterval(installTimer);installTimer=null;}
}
function finishInstall(){
  stopInstallTimer();
  installProgress=100;
  installRunning=false;
  installDone=true;
  renderInstallModal();
}
function startInstall(){
  stopInstallTimer();
  installRunning=true;installDone=false;installProgress=0;installSubstep=0;installLog=[];
  const net=installMode==='net';
  const prefix=installPath.trim();
  const proxy=proxyFlag();
  if(net){
    installLog.push({text:'$ npm install '+PKG+'@'+installVersion+' --prefix '+prefix+' --no-audit --no-fund'+proxy,cls:''});
    installLog.push({text:proxy?'npm 代理 '+proxy.trim().replace(/^--proxy /,'')+'（仅本次安装，不写全局配置）':'未配置代理：直连 registry.npmjs.org',cls:'c-dim'});
  }
  renderInstallModal();
  const netScript=[
    {p:14,line:'npm http fetch GET 200 https://registry.npmjs.org/'+PKG,cls:'c-dim'},
    {p:42,line:'npm http fetch GET 200 '+PKG_TARBALL,cls:'c-dim'},
    {p:66,line:'added 1 package, and audited 1 package in 3s',cls:''},
    {p:86,line:'$ ln -sfn '+prefix+'/node_modules/.bin/ocx '+prefix.replace(/(\/runtime)?(\/opencodex)?$/,'')+'/bin/ocx',cls:'c-dim'},
    {p:100,line:'运行来源已切换为「托管安装」',cls:'c-ok'}
  ];
  const fileScript=[{p:22,sub:0},{p:52,sub:1},{p:80,sub:1},{p:100,sub:2}];
  const script=net?netScript:fileScript;
  let step=0;
  installTimer=setInterval(()=>{
    const item=script[step];
    if(!item){finishInstall();return;}
    installProgress=item.p;
    if(net&&item.line) installLog.push({text:item.line,cls:item.cls||''});
    if(!net&&typeof item.sub==='number') installSubstep=item.sub;
    step++;
    renderInstallModal();
    if(installProgress>=100) finishInstall();
  },620);
}
function openRuntimeInstall(mode){
  installMode=mode||'net';
  installPick=null;
  installAck=false;
  stopInstallTimer();
  installRunning=false;installDone=false;installProgress=0;installSubstep=0;installLog=[];
  openModal('安装 OpenCodex','<div id="installHost"></div>','开始安装',
    ()=>{
      if(installDone){
        runtimeSource='managed';renderRuntimeSource();
        toast('原型拦截：不会真的写入 '+installPath+'。');
        closeModal();
        return;
      }
      const err=installPathError(installPath);
      if(err){toast('安装位置不可用：'+err);return}
      if(installMode==='file'&&!(installPick&&installPick.ok)){toast('请先导入官方离线包（文件名与包名都要匹配）。');return}
      startInstall();
    },
    {cancelLabel:'取消', hideNote:true, confirmKeepsOpen:true});
  window.__modalOnClose=()=>{stopInstallTimer();installRunning=false;};
  renderInstallModal();
}
function wireDropzone(){
  const dz=document.getElementById('dropzone');
  if(!dz) return;
  dz.addEventListener('dragover',event=>{event.preventDefault();dz.classList.add('hot')});
  dz.addEventListener('dragleave',()=>dz.classList.remove('hot'));
  dz.addEventListener('drop',event=>{event.preventDefault();dz.classList.remove('hot');mockPick('good')});
}
function mockPick(kind){
  if(kind==='good'){
    installPick={name:OFFICIAL_TARBALL_NAME,size:'2.9 MB',sha:'9f3a1c7e…',ok:true};
  }else{
    installPick={name:'opencodex-latest.tgz',size:'2.9 MB',sha:'—',ok:false,
      reason:`拒绝：文件名需匹配 opencodex-<版本>.tgz，且包名必须是 ${PKG}；不会安装非白名单包。`};
  }
  renderInstallModal();
}
