  return `<div class="log-table-wrap"><table class="log-table"><thead><tr><th style="width:76px">时间</th><th style="width:150px">命令</th><th>调用来源</th><th style="width:150px">执行结果</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="t-time">${logEsc(r.t)}</td><td class="t-mono">${logCell(r.cmd)}</td><td>${logCell(r.src)}</td>${logResultCell(r)}</tr>`).join('')}</tbody></table></div>`;
}

// 详情浮层：fixed 定位，避开表格滚动容器的裁剪。
function logTipElement(){
  let el=document.getElementById('logTip');
  if(!el){ el=document.createElement('div'); el.id='logTip'; el.className='log-tip'; el.setAttribute('role','tooltip'); document.body.appendChild(el); }
  return el;
}
function showLogTip(target){
  const detail=target.getAttribute('data-detail')||'';
  if(!detail) return;
  const el=logTipElement();
  el.textContent=detail;
  el.classList.add('show');
  const r=target.getBoundingClientRect();
  const box=el.getBoundingClientRect();
  const left=Math.max(8,Math.min(r.left,window.innerWidth-box.width-8));
  let top=r.bottom+8;
  if(top+box.height>window.innerHeight-8) top=Math.max(8,r.top-box.height-8);
  el.style.left=left+'px';
  el.style.top=top+'px';
}
function hideLogTip(){ const el=document.getElementById('logTip'); if(el) el.classList.remove('show'); }
document.addEventListener('mouseover',event=>{
  const hit=event.target.closest&&event.target.closest('.t-detail-hit');
  if(hit) showLogTip(hit);
});
document.addEventListener('mouseout',event=>{
  const hit=event.target.closest&&event.target.closest('.t-detail-hit');
  if(hit&&!(event.relatedTarget&&hit.contains(event.relatedTarget))) hideLogTip();
});
document.addEventListener('focusin',event=>{
  const hit=event.target.closest&&event.target.closest('.t-detail-hit');
  if(hit) showLogTip(hit); else hideLogTip();
});
// 容器滚动或窗口尺寸变化时浮层位置会失真，直接收起。
window.addEventListener('scroll',hideLogTip,true);
window.addEventListener('resize',hideLogTip);
function logRecordsBody(){
  if(LOG_CATS[logCat].kind==='text') return logTextBody(LOG_MOCK.app.normal);
  return logAuditTable(LOG_MOCK.audit.rows);
}
function logLongTextBody(){
  const raw=LOG_LONG_TEXT;const cut=raw.length>LOG_DISPLAY_CAP;const shown=cut?raw.slice(0,LOG_DISPLAY_CAP):raw;
  return `<div class="log view"><span class="time">14:30:58</span> ${logEsc(shown)}${cut?'<span class="cut-mark">已截断 8 KiB</span>':''}</div>`;
}
function logStaleBanner(){
  return `<div class="log-stale">${logStateIcon('warn')}<span><strong>以下为上次读取内容</strong>，可能已过期（最后成功读取 ${logEsc((logCache[logCat]||{}).time||'—')}）。</span></div>`;
}

function renderLog(){
  const cfg=LOG_CATS[logCat];
  const statusEl=document.getElementById('logStatus');
  const viewEl=document.getElementById('logView');
  if(!statusEl||!viewEl) return;
  const scenBtn=document.querySelector(`#logScenarios button[data-log-scenario="${logScenario}"]`);
  const scenLabel=scenBtn?scenBtn.textContent:logScenario;
  const applicable=LOG_SCEN_APPLICABLE[logScenario].includes(logCat);
  let eff;
  if(logBusy) eff='loading';
  else if(!applicable) eff='normal';
  else eff=logScenario;

  const flags=[];
  if(eff==='capped') flags.push('<span class="log-flag warn">已截断</span>');
  if(eff==='missing') flags.push('<span class="log-flag warn">未生成</span>');
  if(eff==='error') flags.push('<span class="log-flag warn">读取失败</span>');
  if(eff==='timeout') flags.push('<span class="log-flag warn">读取超时</span>');

  let body='';let main='';let notes='';
  const hasRows=(eff==='normal'||eff==='capped'||eff==='longtext');
  const time=logNowTime();
  if(eff==='loading'){
    main=`<span>${logEsc(cfg.read)}</span>`;
    body=`<div class="log-loading"><span class="log-spinner" aria-hidden="true"></span><span>${logEsc(cfg.read)}</span></div>`;
  }else if(eff==='longtext'){
    body=logLongTextBody();logCache[logCat]={html:body,time};
  }else if(hasRows){
    body=logRecordsBody();logCache[logCat]={html:body,time};
  }else if(eff==='empty'){
    body=logStatePanel({tone:'',title:`暂无${cfg.label}记录`,desc:cfg.kind==='text'?'当前应用日志文件为空；新的管理器操作会继续写入。':'本次读取没有返回记录。',acts:[{label:'刷新',act:'refresh'}]});
  }else if(eff==='missing'){
    // 不可用时不自动跨分类回退；只在用户主动点击时切换并更新选中项。
    const acts=[{label:'刷新',act:'refresh'}];
    if(logCat!=='app') acts.push({label:'查看应用日志',act:'view-app'});
    body=logStatePanel({tone:'warn',title:`尚未生成${cfg.label}文件`,desc:'未在来源位置找到文件；产生对应记录后即可读取。',acts});
  }else if(eff==='error'||eff==='timeout'){
    body=logStatePanel({tone:'error',title:eff==='timeout'?'读取超时':'本次读取失败，请重试',desc:eff==='timeout'?'命令在规定时间内未返回；本次读取资源已释放，代理未被终止。':'读取过程出错；不跨分类替换内容。',acts:[{label:'重试',act:'refresh'}]});
    // 失败/超时保留本分类上次成功内容，但显式标注其可能已过期；不跨分类替换。
    if(logCache[logCat]) body+=logStaleBanner()+logCache[logCat].html;
  }

  if(hasRows){
    main=`<span class="log-src">来源 <code>${logEsc(cfg.path)}</code></span><span class="dot-sep">·</span><span>${cfg.kind==='text'?'最近 200 行':'最近 200 条'}</span><span class="dot-sep">·</span><span>更新于 ${time}</span>`;
  }else if(eff!=='loading'){
    main=`<span class="log-src">来源 <code>${logEsc(cfg.path)}</code></span>`;
  }

  if(eff==='capped') notes+=`<p class="log-note cap">内容超过本次显示上限，已截断；此处不代表完整历史。</p>`;
  if(!applicable&&!logBusy) notes+=`<p class="log-note">演示状态「${logEsc(scenLabel)}」不适用于当前分类，已显示正常记录。</p>`;

  const toolbar=`<div class="log-toolbar"><button class="btn ghost" id="logPanelEntry" data-log-act="panel" title="请求日志由官方面板负责；本入口只导航到面板">面板请求日志</button>${logCat==='app'?'<button class="btn ghost" data-log-act="clear">清理日志</button>':''}<button class="btn" data-log-act="refresh" ${eff==='loading'?'disabled':''}>刷新</button></div>`;
  statusEl.innerHTML=`<div class="log-status-main">${main}${flags.join('')}</div>${toolbar}`;
  viewEl.innerHTML=body+notes;
}

function updateLogDemoButtons(){
  document.querySelectorAll('#logScenarios button').forEach(b=>{
    const ok=(LOG_SCEN_APPLICABLE[b.dataset.logScenario]||[]).includes(logCat);
    b.disabled=!ok;
    b.classList.toggle('active',ok&&b.dataset.logScenario===logScenario);
    b.title=ok?'':'当前分类不适用该演示状态';
  });
  document.querySelectorAll('#logRunStates button').forEach(b=>{
    b.classList.toggle('active',b.dataset.logRun===logRunState);
  });
}
function cancelLogRead(){
  if(logRefreshTimer){clearTimeout(logRefreshTimer);logRefreshTimer=null;}
  logBusy=false;
}
function setLogCat(cat){
  if(!LOG_CATS[cat]) return;
  logCat=cat;
  cancelLogRead(); // 离开分类：取消旧读取，避免迟到结果串类。
  document.querySelectorAll('.log-cats button').forEach(b=>{
    const on=b.dataset.logCat===cat;
    b.classList.toggle('active',on);
    b.setAttribute('aria-selected',on?'true':'false');
  });
  document.getElementById('logView')?.setAttribute('aria-labelledby',`logTab-${cat}`);
  renderLog();
  updateLogDemoButtons();
}
function logRefresh(){
  if(logBusy) return;
  logBusy=true;renderLog();
  if(logRefreshTimer) clearTimeout(logRefreshTimer);
  logRefreshTimer=setTimeout(()=>{logRefreshTimer=null;logBusy=false;renderLog();toast('原型模拟：已按当前分类读取一次；不发起真实读取、不启动代理。');},650);
}
function handleLogClick(event){
  const btn=event.target.closest('[data-log-act]');
  if(!btn||btn.disabled) return;
  const act=btn.dataset.logAct;
  if(act==='refresh'){
    logRefresh();
  }else if(act==='view-app'){
    logScenario='normal';
    setLogCat('app');
  }else if(act==='clear'){
    openModal('清理日志','将清空「应用日志」当前视图；原始文件仍由管理器数据根的日志分区按保留策略管理。该清理只作用于管理器本地日志分区，不涉及官方请求数据或活跃数据根审计文件。','清理',()=>{logCache.app=null;logScenario='empty';renderLog();updateLogDemoButtons();toast('原型模拟：应用日志视图已清理。');});
  }else if(act==='panel'){
    openLogPanelEntry();
  }
}
document.querySelectorAll('.log-cats button').forEach(button=>{
  button.addEventListener('click',()=>setLogCat(button.dataset.logCat));
});
document.getElementById('logView')?.addEventListener('click',handleLogClick);
document.getElementById('logStatus')?.addEventListener('click',handleLogClick);
document.getElementById('logScenarios')?.addEventListener('click',event=>{
  const b=event.target.closest('button[data-log-scenario]');
  if(!b||b.disabled) return;
  logScenario=b.dataset.logScenario;
  cancelLogRead();
  renderLog();
  updateLogDemoButtons();
});
document.getElementById('logRunStates')?.addEventListener('click',event=>{
  const b=event.target.closest('button[data-log-run]');
  if(!b) return;
  logRunState=b.dataset.logRun;
  renderLog();
  updateLogDemoButtons();
});

// 官方面板入口：只导航，不在管理器里重复实现请求日志列表。
// 代理未运行 → 说明原因，不自动启动、不切走当前分类；加载失败 → 如实失败并给重试，不伪装成空。
function openLogPanelEntry(){
  if(logRunState!=='running'){
    openModal('官方面板','<p class="modal-lead">代理未运行，请先启动后查看。</p><p>请求日志由官方面板负责；本入口不会自动启动代理，也不会改变当前日志分类。</p>','知道了',null,{hideConfirm:true,cancelLabel:'知道了'});
    return;
  }
  if(logPanelState==='fail'){
    openModal('官方面板加载失败','<p class="modal-lead">面板没有加载成功；请求日志不会被显示为空。</p><p>两类本地日志不受影响，可继续查看；「重试」会再次尝试进入面板。</p>','重试',()=>{toast('原型模拟：重试进入官方面板；不预加载、不新建窗口。');},null);
    return;
  }
  setRoute('panel');
  toast('原型模拟：进入应用内官方面板；请在面板中选择「日志与调试」。');
}
document.getElementById('logPanelStates')?.addEventListener('click',event=>{
  const b=event.target.closest('button[data-log-panel]');
  if(!b) return;
  logPanelState=b.dataset.logPanel;
  document.querySelectorAll('#logPanelStates button').forEach(x=>x.classList.toggle('active',x===b));
});
setLogCat('app');
window.renderLog=renderLog;

