function setRoute(route, replace=false){
  window.prototypeSelect?.close();
  const legacyRoutes={process:'overview',config:'settings',webdav:'settings',upgrade:'settings',about:'settings'};
  let {route:hashRoute}=parseRouteHash(route);
  hashParams=parseRouteHash(route).params;
  if(hashRoute==='webdav'||hashRoute==='settings'&&['migration','sync'].includes(hashParams.get('section'))){
    const syncTab=hashRoute==='webdav'||hashParams.get('section')==='sync'?'webdav':'file';
    hashRoute='sync';hashParams=new URLSearchParams({tab:syncTab});
  }
  const aboutRedirect=hashRoute==='about';
  const next=legacyRoutes[hashRoute]||((routes[hashRoute]||hashRoute==='panel')?hashRoute:'overview');
  if(next==='panel'){
    currentRoute='panel';
    showPanel(true,true);
    // 路由属性必须与其它路由一样投影到位：否则 data-route 停在 overview，
    // 概览专属规则（.main 内距、#statePill 等）会继续命中面板页，造成布局错位。
    document.documentElement.setAttribute('data-route','panel');
    document.querySelectorAll('.route-section').forEach(section=>section.classList.toggle('active',section.id==='panelSection'));
    document.querySelectorAll('.nav button[data-route]').forEach(button=>{button.classList.toggle('active',button.dataset.route==='panel');});
    return;
  }
  currentRoute=next;
  document.documentElement.setAttribute('data-route',next);
  document.querySelectorAll('.route-section').forEach(section=>{
    section.classList.toggle('active',section.id===`route-${next}`);
  });
  document.querySelectorAll('.nav button[data-route]').forEach(button=>{
    button.classList.toggle('active',button.dataset.route===next);
  });
  const meta=routes[next]||{title:'OpenCodex 运行概览',subtitle:'发现安装、切换数据目录、托管官方启停子进程并观察状态。'};
  document.getElementById('routeTitle').textContent=meta.title;
  document.getElementById('routeSubtitle').textContent=meta.subtitle;
  if(next==='tray') renderTray();
  if(aboutRedirect) showSettingsSection('about');
  if(next!=='panel') document.body.classList.remove('panel-mode');
  if(next!=='roadmap'&&next!=='components'){
    try{window.localStorage.setItem('ocx-route',next)}catch(e){}
  }else if(next==='roadmap'){
    try{window.localStorage.removeItem('ocx-route')}catch(e){}
  }
  const query=hashParams.toString();
  const hash=`#${next}${query?`?${query}`:''}`;
  if(location.hash!==hash){
    if(replace) history.replaceState(null,'',hash); else location.hash=hash;
  }
}

function renderRecentEvents(kind){
  const list=document.getElementById('recentEventsList');
