function createAnchorTitles(){
// 不往 card-head 注入锚点按钮：卡头右侧由通用注释标记占用，锚点功能与样式影响一并移除。
document.querySelectorAll('.card-head').forEach(head=>{
  const card=head.closest('[id]');
  if(!card) return;
  card.dataset.anchor = card.id.replace(/^card-/,'').replace(/-history$/,'').replace('general-prefs','general').replace('settings-skills','skills').replace('settings-mcp','mcp');
});
document.querySelectorAll('.recent-events-head, .ovb-detail > summary').forEach(head=>{
  const card=head.closest('[id]');
  const title=head.querySelector('h2, h3, span');
  if(!card||!title||head.querySelector('.anchor-btn')) return;
  const holder=document.createElement('div');
  holder.className='card-head-title';
  title.parentNode.insertBefore(holder,title);
  holder.appendChild(title);
  const button=document.createElement('button');
  button.type='button';
  button.className='anchor-btn';
  button.title='复制锚点链接';
  button.setAttribute('aria-label','复制锚点链接');
  button.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10 13a5 5 0 0 0 7 0l2-2a5 5 0 0 0-7-7l-1 1"/><path d="M14 11a5 5 0 0 0-7 0l-2 2a5 5 0 0 0 7 7l1-1"/></svg>';
  button.addEventListener('click',event=>{
    event.stopPropagation();
    const route=currentRoute||'overview';
    let anchor=card.id.replace(/^card-/,'');
    if(anchor.endsWith('-history')) anchor='logs';
    if(anchor==='general-prefs') anchor='general';
    if(anchor==='settings-skills') anchor='skills';
    if(anchor==='settings-mcp') anchor='mcp';
    const hash=buildAnchorHash(route,anchor);
    history.replaceState(null,'',hash);
    requestAnimationFrame(()=>flashAnchor(card));
    const text=location.protocol==='file:' ? decodeURI(location.href) : location.href;
    if(navigator.clipboard?.writeText) navigator.clipboard.writeText(text).catch(()=>{});
    toast('原型模拟：已复制标题锚点。');
  });
  holder.appendChild(button);
});
}
let opResultKey='none';
function renderOpResult(){
  const slot=document.querySelector('[data-b="opresult"]');
  if(!slot) return;
  const cfg=OP_RESULTS[opResultKey];
  if(!cfg){slot.hidden=true;slot.innerHTML='';return;}
  slot.hidden=false;
  slot.dataset.tone=cfg.tone||'';
  const list=arr=>`<ul>${arr.map(x=>`<li>${x}</li>`).join('')}</ul>`;
  const body=[
    cfg.done&&cfg.done.length?`<div>已完成：${list(cfg.done)}</div>`:'',
    cfg.undone&&cfg.undone.length?`<div>未完成 / 影响：${list(cfg.undone)}</div>`:'',
    cfg.next?`<div class="ovb-result-next">下一步：${cfg.next}</div>`:''
  ].join('');
  slot.innerHTML=`<div class="ovb-result-head"><span>${cfg.title}</span><span class="tag">${cfg.tag}</span></div><div>${cfg.detail}</div>${body}`;
}

function render(){

  const s=scenarios[currentState];
  const model=STATE_MODEL[currentState]||STATE_MODEL.loading;
  const ml=MAINLINE[model.main];
  const pillCls=model.main==='running'?'state-running':model.main==='confirming'?'state-starting':'state-muted';
  statePill.textContent=ml.label;
  statePill.className='state-pill '+pillCls;
  const installKnown=!['loading','not_found'].includes(currentState);
  const values={
    health:s.health,
    port:s.port,
    pid:s.pid,
    version:installKnown?installFound.version.split('（')[0]:'—',
    runtime:installKnown?installFound.runtime:'—',
    home:installKnown?(window.dataPathsPrototype?.current() || DataPaths.paths('macos')).home:'—',
    root:installKnown?(window.dataPathsPrototype?.current() || DataPaths.paths('macos')).root:'—',
    rootshort:installKnown?(window.dataPathsPrototype?.current() || DataPaths.paths('macos')).root:'—',
    detailfacts:installKnown
      ?`v${installFound.version.split('（')[0]} · ${installFound.runtime.replace('ChatGPT Codex runtime ','Codex runtime ')} · ${(window.dataPathsPrototype?.current() || DataPaths.paths('macos')).root}`
      :'尚未探测到安装'
  };
  Object.keys(values).forEach(key=>{
    document.querySelectorAll(`[data-b="${key}"]`).forEach(el=>{
      el.textContent=values[key];
      // 概览摘要行里的数据目录会按可用宽度截断，title 负责给出完整值。
      if(key==='rootshort') el.title=values[key];
    });
  });
  // 一个运行主线：主线标签只表达运行事实，不被支线或问题抢占。
  document.querySelectorAll('[data-b="statebadge"]').forEach(el=>{el.className='ovc-badge'+(ml.badge?` ${ml.badge}`:'')});
  document.querySelectorAll('[data-b="statetext"]').forEach(el=>{el.textContent=ml.label});
  document.querySelectorAll('[data-b="statepill"]').forEach(el=>{el.textContent=ml.label;el.className='state-pill '+pillCls});
  const br=model.branch||{};
  // 同一行内联提示：持续问题（warning/danger）或中性说明（info）。空闲/无问题时不出提示，避免与主线和按钮重复。
  const inline=model.problem
    ? {text:model.problem.title,tone:model.problem.kind}
    : (model.note?{text:model.note.text,tone:model.note.tone}:null);
  const problemSlot=document.querySelector('[data-b="problem"]');
  if(problemSlot){
    if(inline){problemSlot.hidden=false;problemSlot.className='ovb-problem '+(inline.tone||'info');problemSlot.textContent=inline.text;}
    else{problemSlot.hidden=true;problemSlot.textContent='';}
  }
  // 第二行只承载「进行中 / 结果 / 待办」这类有信息量的支线；空闲与中性说明不再重复占一行。
  const branchRow=document.querySelector('[data-b="brancher"]');
  if(branchRow){
    const showBranch=['progress','result','action'].includes(br.kind);
    branchRow.hidden=!showBranch;
    if(showBranch){
      const label=document.querySelector('[data-b="branchlabel"]');
      label.textContent=br.label||'';
      label.className='ob-label'+(br.tone?` tone-${br.tone}`:'');
      document.querySelectorAll('[data-b="branchspin"]').forEach(el=>{el.hidden=br.kind!=='progress'});
      const chip=document.querySelector('[data-b="branchchip"]');
      if(chip){chip.hidden=br.kind!=='result';chip.textContent=br.kind==='result'?'结果':'';}
      document.querySelector('[data-b="branchhint"]').textContent=br.hint||'';
    }
  }
  // 端口只在有运行观测时展示；未运行不得暗示正在监听。
  document.querySelectorAll('[data-fact="port"]').forEach(el=>{el.hidden=model.main!=='running'});
  renderOpResult();
  // 动作按同源能力渲染：主要操作直接露出，低频操作进「更多」，不渲染无解释的禁用按钮。
  const actionsByState={
    loading:[],
    not_found:['refresh'],
    stopped:['start','refresh'],
    starting:['refresh'],
    pending:['refresh'],
    running:['panel','stop','restart','logs'],
    starting_failed:['start','logs'],
    /* at_risk 的进程事实就是「未运行」：概览动作与 stopped 一致（2026-10-03 用户确认）。 */
    at_risk:['start','refresh'],
    external_takeover:['advice','refresh'],
    unreachable:['refresh','logs']
  };
  /* 「查看日志」已提到主行；真实软件概览没有「更多」折叠层（刷新只在顶栏 / 门禁态），
     2026-10-09 软件实证后原型删除 .ovb-more 组件，动作集合与软件一致。 */
  const envBlocked=envGateActive&&envState!=='ready';
  const allowedActions=envBlocked?['refresh']:(actionsByState[currentState]||[]);
  document.querySelectorAll('[data-act]').forEach(el=>{el.hidden=!allowedActions.includes(el.dataset.act)});
  document.querySelector('.ovb-detail')?.toggleAttribute('hidden',envBlocked);
  document.getElementById('mods')?.classList.toggle('view-hidden',envBlocked);
  document.getElementById('recentEventsSection')?.toggleAttribute('hidden',envBlocked);
  document.querySelectorAll('[data-act="start"]').forEach(el=>{
    el.textContent=currentState==='starting_failed'?'重试启动':'启动 OpenCodex';
  });

  setInstall();

  renderNotifications();

  // 日志历史的分类由用户在页面内选择，不随运行状态自动回退或切换；
  // 因此 render() 不再改写日志内容，交由日志模块按「分类 + 演示状态」独立渲染。

  renderRecentEvents(
    ['at_risk','external_takeover'].includes(currentState)
      ? 'risk'
      : (['starting_failed','unreachable'].includes(currentState)?'error':'normal')
  );

  const controls={
    start:document.querySelectorAll('[data-control="start"]'),
    stop:document.querySelectorAll('[data-control="stop"]'),
    restart:document.querySelectorAll('[data-control="restart"]')
  };
  controls.start.forEach(button=>button.disabled=!['stopped','not_found','starting_failed'].includes(currentState));
  controls.stop.forEach(button=>button.disabled=!['running','pending'].includes(currentState));
  controls.restart.forEach(button=>button.disabled=!['running','pending'].includes(currentState));
}

