let trayOs='mac';
let trayState='stopped';
let trayOpen=false;
/* launchWithCodex 默认关闭：方便在原型里点开「随 Codex 启动 OpenCodex」直接看安装进行态。
   托盘菜单里同名项与设置页这一行是同一配置源，故一起为「关闭」，避免原型自相矛盾。 */
const trayQuickSettings={launchWithCodex:false,showMainWindow:true};
// 托盘标题只讲进程事实：at_risk（应用内「存在风险」）在托盘显示「未运行」，
// 风险结论与说明句不写进托盘（2026-09-24 用户决策；托盘菜单项会被长文案撑宽）。
const trayStateLabels={stopped:'未运行',starting:'启动中',running:'运行中',starting_failed:'启动失败',external_takeover:'外部接管',at_risk:'未运行'};
const trayHints={
  start:{stopped:'可用',starting:'启动中',running:'已运行',starting_failed:'可重试',external_takeover:'先确认'},
  stop:{stopped:'未运行',starting:'稍后停止',running:'可用',starting_failed:'未运行',external_takeover:'需先确认'},
  restart:{stopped:'未运行',starting:'稍后重启',running:'可用',starting_failed:'可重试',external_takeover:'需先确认'},
  panel:{stopped:'需运行',starting:'等待就绪',running:'可用',starting_failed:'不可用',external_takeover:'只读'},
  doctor:{stopped:'可选',starting:'等待',running:'可选',starting_failed:'建议',external_takeover:'建议'}
};
const trayDotMap={stopped:'stopped',starting:'starting',pending:'starting',running:'running',starting_failed:'starting_failed',unreachable:'unreachable',at_risk:'at_risk',external_takeover:'external_takeover'};
function renderTray(){
  const shell=document.querySelector('[data-tray-shell]');
  if(!shell) return;
  shell.dataset.trayShell=trayOs;
  shell.dataset.trayOpen=trayOpen?'true':'false';
  shell.querySelectorAll('[data-tray-toggle]').forEach(button=>{
    button.classList.toggle('active',trayOpen);
    button.setAttribute('aria-expanded',trayOpen?'true':'false');
  });
  shell.querySelectorAll('[data-tray-label]').forEach(el=>el.textContent=trayStateLabels[trayState]||trayState);
  shell.querySelectorAll('[data-tray-hint]').forEach(el=>{
    el.textContent=trayHints[el.dataset.trayHint]?.[trayState]||'—';
  });
  shell.querySelectorAll('.tray-dot').forEach(el=>{
    el.className='tray-dot '+(trayDotMap[trayState]||'stopped');
  });
  shell.querySelectorAll('.tray-logo').forEach(el=>{
    const state=trayDotMap[trayState]||'stopped';
    el.classList.remove('state-running','state-starting','state-pending','state-starting_failed','state-unreachable','state-at_risk','state-external_takeover');
    if(state!=='stopped') el.classList.add('state-'+state);
  });
  shell.querySelector('.tray-menu.mac')?.classList.toggle('hidden',trayOs!=='mac');
  shell.querySelector('.tray-menu.mac')?.classList.toggle('open',trayOs==='mac'&&trayOpen);
  shell.querySelector('.tray-menu.windows')?.classList.toggle('hidden',trayOs!=='windows');
  shell.querySelector('.tray-menu.windows')?.classList.toggle('open',trayOs==='windows'&&trayOpen);
  document.querySelectorAll('#settings-general [aria-label="随 Codex 启动 OpenCodex"], #settings-general [aria-label="启动时打开主界面"]').forEach(toggle=>{
    const key=toggle.getAttribute('aria-label')==='随 Codex 启动 OpenCodex'?'launchWithCodex':'showMainWindow';
    toggle.setAttribute('aria-checked',Boolean(trayQuickSettings[key])?'true':'false');
  });
  shell.querySelectorAll('[data-tray-setting]').forEach(el=>{
    const value=Boolean(trayQuickSettings[el.dataset.traySetting]);
    el.setAttribute('aria-checked',value?'true':'false');
    const mark=el.querySelector('.toggle-mark');
    if(mark) mark.textContent=value?'开启':'关闭';
  });
  shell.querySelector('.tray-menubar.mac')?.classList.toggle('hidden',trayOs!=='mac');
  shell.querySelector('.tray-statusbar.windows')?.classList.toggle('hidden',trayOs!=='windows');
  document.querySelectorAll('[data-tray-os]').forEach(button=>{
    button.classList.toggle('active',button.dataset.trayOs===trayOs);
  });
  document.querySelectorAll('[data-tray-state]').forEach(button=>{
    button.classList.toggle('active',button.dataset.trayState===trayState);
  });
}
document.addEventListener('click',event=>{
  const toggle=event.target.closest('[data-tray-toggle]');
  if(toggle){trayOpen=!trayOpen;renderTray();return;}
  if(trayOpen&&!event.target.closest('.tray-menu')){trayOpen=false;renderTray();}
  const os=event.target.closest('[data-tray-os]');
