      ?`原型拦截：随 Codex 启动已${trayQuickSettings[key]?'开启':'关闭'}；同步官方同源配置。`
      :`原型拦截：启动时显示主界面已${trayQuickSettings[key]?'开启':'关闭'}。`);
    return;
  }
  const state=event.target.closest('[data-tray-state]');
  if(state){trayState=state.dataset.trayState;renderTray();setState(trayState);return;}
  const item=event.target.closest('.tray-item[data-prototype-action^="tray-"]');
  if(item&&!item.disabled){
    const action=item.dataset.prototypeAction.replace('tray-','');
    const messages={
      start:'原型拦截：会委托管理器启动 OpenCodex。',
      stop:'原型拦截：会委托管理器停止 OpenCodex。',
      restart:'原型拦截：会委托管理器重启 OpenCodex。',
      'open-main':'原型拦截：会打开主界面。',
      'open-panel':'原型拦截：会打开官方面板。',
      'open-logs':'原型拦截：会打开诊断中心。',
      doctor:'原型拦截：会打开诊断中心并运行 Doctor。',
      quit:'原型拦截：会退出桌面壳。'
    };
    toast(messages[action]||'原型拦截：托盘动作不执行真实操作。');
  }
});
window.__lastAnchorHash='';
window.addEventListener('hashchange',()=>{
  const raw=location.hash;
  setRoute(raw.slice(1),true);
  if(window.__lastAnchorHash!==raw){
    window.__lastAnchorHash=raw;
