function parseRouteHash(hash){
  const raw=String(hash||'').replace(/^#/,'');
  const [route,query='']=raw.split('?');
  return {route,params:new URLSearchParams(query)};
}

function buildAnchorHash(route,anchor){
  if(route==='settings') return `#settings?section=${anchor}`;
  if(route==='extensions') return `#extensions?tab=${anchor}`;
  if(route==='logs') return `#logs?tab=${anchor}`;
  return `#${route}`;
}

function flashAnchor(card){
  if(!card) return;
  requestAnimationFrame(()=>requestAnimationFrame(()=>card.classList.add('card-anchor-flash')));
  window.setTimeout(()=>card.classList.remove('card-anchor-flash'),1400);
}

function anchorCard(route,anchor){
  const candidates=[`card-${anchor}`,anchor,anchor==='general'?'card-general-prefs':anchor==='backup'?'card-backup-data':anchor==='extensions'?'card-settings-mcp':anchor==='upgrade'?'card-upgrade-official':anchor==='about'?'card-about':anchor==='mcp'?'card-ext-mcp':['doctor','logs','notifications'].includes(anchor)?'card-diag-history':anchor];
  for(const id of candidates){
    const card=document.getElementById(id);
    if(card) return card;
  }
  return null;
}

function applyHashAnchor(hash,silent=false){
  const {route,params}=parseRouteHash(hash);
  // 诊断中心：`?tab=` 显式指定分区时同步激活对应 Tab（无 `tab` 时保持默认落地「环境诊断」）。
  if(route==='logs'){
    const tab=params.get('tab');
    if(['doctor','logs','notifications'].includes(tab)){
      document.querySelectorAll('[data-diag-tab]').forEach(item=>item.classList.toggle('active',item.dataset.diagTab===tab));
      document.querySelectorAll('.diag-view').forEach(view=>view.classList.toggle('active',view.id===`diag-${tab}`));
    }
  }
  const anchor=params.get('card')||params.get('section')||params.get('tab');
  if(!anchor) return;
  const card=anchorCard(route,anchor);
  if(!card||card.hidden) return;
  card.classList.remove('card-anchor-flash');
  window.setTimeout(()=>{
    requestAnimationFrame(()=>{
      const scroller=card.closest('.main');
      const rect=card.getBoundingClientRect();
      const viewport=scroller?.getBoundingClientRect();
      const fullyVisible=viewport&&rect.top>=viewport.top-1&&rect.bottom<=viewport.bottom+1;
      if(scroller&&!fullyVisible){
        scroller.scrollTop=0;
        void scroller.offsetHeight;
        const top=card.getBoundingClientRect().top-scroller.getBoundingClientRect().top+scroller.scrollTop-8;
        if(Math.abs(scroller.scrollTop-top)>2) scroller.scrollTo({top,behavior:'auto'});
      }else if(!scroller){
        card.scrollIntoView({behavior:'auto',block:'start'});
      }
      requestAnimationFrame(()=>{
        const rect=card.getBoundingClientRect();
        const view=scroller?.getBoundingClientRect();
        if(!view||rect.top>=view.top-1&&rect.bottom<=view.bottom+1){
          card.classList.add('card-anchor-flash');
          window.setTimeout(()=>card.classList.remove('card-anchor-flash'),1400);
        }else{
          flashAnchor(card);
        }
      });
      card.dataset.anchorActive='1';
      window.setTimeout(()=>delete card.dataset.anchorActive,1400);
    });
  },silent?120:60);
}

