// 「随 Codex 启动 OpenCodex」的写入进行态（原型先行）。
// 真实语义：读走 `ocx codex-shim status`，写走 `ocx codex-shim install|uninstall`；
// 官方安装先做一次探针，真机实测 ~20 秒且**不提供分步进度** —— 所以给不确定进度条 + 已用时间，
// 不编百分比（界面不撒谎）。时序刻意分两段：先「准备」延迟，再逐步跑写入，完成才打开开关。
// 具体指令清单渲染进框内下拉，供用户查证「到底执行了什么」。
const shimWritePlan={
  install:{
    title:'正在安装官方 shim',
    prepare:'正在准备：解析官方 CLI 与探针前提…',
    prepareHint:'准备阶段：正式写入尚未开始。',
    hint:'官方会先做一次探针校验，通常 10–30 秒；期间请勿退出应用。',
    steps:[
      {cmd:'ocx codex-shim status',note:'读当前状态',ms:700},
      {cmd:'ocx codex-shim install',note:'写入官方 wrapper（含探针校验）',ms:2400},
      {cmd:'ocx codex-shim status',note:'读回确认',ms:600},
    ],
    result:'已安装官方 shim：把 Codex 启动器替换为官方 wrapper，原可执行文件备份为 codex.opencodex-real；之后启动 Codex 会自动运行 ocx ensure。',
    hold:1400,
    done:'原型模拟：官方 shim 安装完成，开关已开启；不执行真实写入。',
  },
  uninstall:{
    close:true,
    title:'正在关闭官方 shim',
    prepare:'正在准备：解析官方 CLI 与还原目标…',
    prepareHint:'准备阶段：正式写入尚未开始。',
    hint:'关闭只把 Codex 启动器还原成原始可执行文件；通常几秒内完成，比开启快得多。',
    steps:[
      {cmd:'ocx codex-shim uninstall',note:'移除官方 wrapper，还原 codex 原始可执行文件',ms:1100},
      {cmd:'ocx codex-shim status',note:'读回确认已还原',ms:500},
    ],
    result:'已关闭官方 shim：移除 wrapper、把 Codex 启动器还原成原始可执行文件，备份 codex.opencodex-real 已清理；Codex 启动不再自动运行 ocx ensure。',
    hold:2000,
    done:'原型模拟：已还原 Codex 启动器，开关已关闭；不执行真实写入。',
  },
};
let shimPanelTimers=[];   // 本轮写入的所有定时器：{clear:()=>void}
function clearShimPanelTimers(){shimPanelTimers.forEach(t=>t.clear());shimPanelTimers=[];}
function shimLater(fn,ms){const id=window.setTimeout(fn,ms);shimPanelTimers.push({clear:()=>window.clearTimeout(id)});return id;}
function shimEvery(fn,ms){const id=window.setInterval(fn,ms);shimPanelTimers.push({clear:()=>window.clearInterval(id)});return id;}
// 供测试在收尾后清理：把面板复位到初始隐藏态。
window.__shimPanelReset=function(){
  clearShimPanelTimers();
  const root=document.querySelector('[data-shim-panel]');
  if(!root)return;
  root.hidden=true;root.dataset.shimState='';
  root.classList.remove('is-prepare','is-run','is-done');
};
function runCodexShimToggle(button){
  if(!button||button.dataset.busy==='1')return;
  const next=button.getAttribute('aria-checked')!=='true';
  const plan=shimWritePlan[next?'install':'uninstall'];
  const root=document.querySelector('[data-shim-panel]');
  button.dataset.busy='1';
  button.disabled=true;
  if(!root)return;
  clearShimPanelTimers();
  const title=root.querySelector('[data-shim-panel-title]');
  const meta=root.querySelector('[data-shim-panel-meta]');
  const hint=root.querySelector('[data-shim-panel-hint]');
  const cmds=root.querySelector('[data-shim-cmds]');
  const details=root.querySelector('[data-shim-details]');
  const detailsToggle=root.querySelector('[data-shim-details-toggle]');
  const result=root.querySelector('[data-shim-panel-result]');
  root.hidden=false;
  root.dataset.shimState='prepare';
  root.classList.remove('is-run','is-done');root.classList.add('is-prepare');
  // 关闭（uninstall）是短动作：不显示开启那根长耗时的进度条，改转圈 + 文案。
  root.classList.toggle('is-close',!!plan.close);
  if(title)title.textContent=plan.prepare;
  if(hint)hint.textContent=plan.prepareHint;
  if(meta)meta.textContent='已用 0s';
  if(result){result.hidden=true;result.textContent='';}
  if(cmds)cmds.innerHTML=plan.steps.map((s,i)=>`<li data-cmd-state="todo" data-cmd-index="${i}"><code>${s.cmd}</code><span>${s.note}</span></li>`).join('');
  if(details)details.hidden=true;
  if(detailsToggle)detailsToggle.setAttribute('aria-expanded','false');

  const startedAt=Date.now();
  shimEvery(()=>{if(meta)meta.textContent='已用 '+Math.round((Date.now()-startedAt)/1000)+'s';},500);

  const finish=()=>{
    root.dataset.shimState='done';
    root.classList.remove('is-prepare','is-run');root.classList.add('is-done');
    if(title)title.textContent=next?'官方 shim 安装完成':'已还原 Codex 启动器';
    if(hint)hint.textContent='完成；开关已更新。';
    // 「对应指令做了什么」：完成时把结果落在框里，留一会儿再收，别一闪而过。
    if(result&&plan.result){result.textContent=plan.result;result.hidden=false;}
    button.disabled=false;
    delete button.dataset.busy;
    button.setAttribute('aria-checked',String(next));
    shimLater(()=>{root.hidden=true;root.classList.remove('is-done','is-close');},plan.hold||700);
    toast(plan.done);
  };

  // 阶段一：准备延迟（不立刻跳进度，避免"点了就完成"的假象）
  shimLater(()=>{
    root.dataset.shimState='run';
    root.classList.remove('is-prepare');root.classList.add('is-run');
    if(title)title.textContent=plan.title;
    if(hint)hint.textContent=plan.hint;
    let acc=0;
    plan.steps.forEach((step,i)=>{
      const isLast=i===plan.steps.length-1;
      const startAt=acc;
      shimLater(()=>{
        const li=cmds&&cmds.querySelector(`[data-cmd-index="${i}"]`);
        if(li)li.dataset.cmdState='run';
      },startAt);
      acc+=step.ms;
      shimLater(()=>{
        const li=cmds&&cmds.querySelector(`[data-cmd-index="${i}"]`);
        if(li)li.dataset.cmdState='done';
        if(isLast)finish();
      },acc);
    });
  },900);
}

