const extensionPagination={
  skills:{page:1,size:10,items:[]},
  mcp:{page:1,size:10,items:[]}
};

function paginateExtension(kind){
  const state=extensionPagination[kind];
  const listSelector=kind==='skills'?'#skillsList':'#mcpList';
  const allRows=[...document.querySelectorAll(`${listSelector} .skill-row`)];
  const total=state.items.length;
  const pages=Math.max(1,Math.ceil(total/state.size));
  state.page=Math.min(Math.max(1,state.page),pages);
  // 先按筛选结果隐藏全部行，再只显示当前页：未命中筛选的行必须真正隐藏，
  // 否则会出现「计数收敛、列表仍全显示」的假过滤（搜索与分类 chip 都受影响）。
  allRows.forEach(row=>{row.hidden=true;});
  state.items.forEach((row,index)=>{
    if(index>=(state.page-1)*state.size&&index<state.page*state.size) row.hidden=false;
  });
  // 描述被两行截断时加渐隐提示；此处统一重算，覆盖两个列表的筛选、翻页与隐藏/显示切换。
  markClampedDescriptions();
  const root=document.querySelector(`[data-pagination="${kind}"]`);
  if(!root) return;
  root.querySelector('[data-page-summary]').textContent=`${total} / ${allRows.length} 条 · 第 ${state.page} / ${pages} 页`;
  root.querySelector('[data-page-current]').textContent=state.page;
  root.querySelector('[data-page-first]').disabled=state.page===1;
  root.querySelector('[data-page-prev]').disabled=state.page===1;
  root.querySelector('[data-page-next]').disabled=state.page===pages;
  root.querySelector('[data-page-last]').disabled=state.page===pages;
}

function bindExtensionPagination(kind){
  const root=document.querySelector(`[data-pagination="${kind}"]`);
  if(!root) return;
  root.addEventListener('click',event=>{
    const button=event.target.closest('button');
    if(!button) return;
    const state=extensionPagination[kind];
    if(button.hasAttribute('data-page-first')) state.page=1;
    else if(button.hasAttribute('data-page-prev')) state.page--;
    else if(button.hasAttribute('data-page-next')) state.page++;
    else if(button.hasAttribute('data-page-last')) state.page=Math.max(1,Math.ceil(state.items.length/state.size));
    else return;
    if(kind==='skills') applySkillsFilters();
    else applyMcpFilters();
  });
  // 设置页「网络」：代理模式为「手动配置」时才展开协议 / 主机端口 / 例外三行（与软件同条件）。
  const pageSizeRoot=document.querySelector(`[data-page-size="${kind}"] [data-page-size-select]`);
  pageSizeRoot?.addEventListener('selectchange',event=>{
    const value=parseInt(event.detail.value,10);
    if(Number.isFinite(value)) extensionPagination[kind].size=value;
    const trigger=pageSizeRoot.querySelector('.select-trigger .select-value');
    if(trigger) trigger.textContent=`${value} 条`;
    if(kind==='skills') applySkillsFilters();
    else applyMcpFilters();
  });
}

function applyMcpFilters(){
  const activeChip=document.querySelector('.skills-chip.active[data-mcp-filter]');
  const filter=activeChip?.dataset.mcpFilter||'all';
