// 扩展管理 → Skills：点击「名称 + 描述」单元格打开只读详情弹窗。
// Skill 详情里的 Markdown 渲染：先把整段文本转义，再套 Markdown 标记——描述里的 HTML 不会被当作标签执行。
// 链接只保留文字（原型不做外链）。支持 1–3 级标题、有序 / 无序列表、引用、围栏代码、加粗与行内代码。
function renderSkillMarkdown(text){
  const inline=value=>logEsc(value)
    .replace(/`([^`]+)`/g,'<code>$1</code>')
    .replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>')
    .replace(/\[([^\]]+)\]\([^)\s]+\)/g,'$1');
  const lines=String(text==null?'':text).replace(/\r\n?/g,'\n').split('\n');
  const html=[];let listTag=null;const para=[];
  const flushPara=()=>{if(para.length){html.push('<p>'+inline(para.join(' '))+'</p>');para.length=0;}};
  const closeList=()=>{if(listTag){html.push('</'+listTag+'>');listTag=null;}};
  for(let i=0;i<lines.length;i++){
    const line=lines[i];
    if(/^\s*```/.test(line)){
      flushPara();closeList();
      const block=[];
      for(i++;i<lines.length&&!/^\s*```/.test(lines[i]);i++) block.push(lines[i]);
      html.push('<pre><code>'+logEsc(block.join('\n'))+'</code></pre>');
      continue;
    }
    if(!line.trim()){flushPara();closeList();continue;}
    const head=line.match(/^(#{1,3})\s+(.*)$/);
    if(head){
      flushPara();closeList();
      const level=head[1].length>=3?'h5':'h4';
      html.push('<'+level+'>'+inline(head[2].trim())+'</'+level+'>');
      continue;
    }
    const bullet=line.match(/^\s*[-*]\s+(.*)$/);
    const ordered=line.match(/^\s*\d+[.)]\s+(.*)$/);
    if(bullet||ordered){
      flushPara();
      const want=bullet?'ul':'ol';
      if(listTag!==want){closeList();html.push('<'+want+'>');listTag=want;}
      html.push('<li>'+inline((bullet||ordered)[1].trim())+'</li>');
      continue;
    }
    const quote=line.match(/^>\s?(.*)$/);
    if(quote){flushPara();closeList();html.push('<blockquote>'+inline(quote[1].trim())+'</blockquote>');continue;}
    closeList();
    para.push(line.trim());
  }
  flushPara();closeList();
  return html.join('');
}
