function openExtensionDetail(row){
  const info=row&&row.querySelector('.skill-info');if(!info)return;
  const isMcp=!!row.closest('#mcpList'),name=info.querySelector('.skill-title h3')?.textContent.trim()||(isMcp?'未命名 MCP':'未命名 Skill');
  const meta=[...info.querySelectorAll('.skill-meta span')].map(el=>el.textContent.trim());
  const data={kind:isMcp?'mcp':'skills',name,description:info.querySelector('p')?.textContent.trim()||'',source:info.querySelector('.skill-title .tag')?.textContent.trim()||'本地',version:meta.find(item=>/^v[\d.]/i.test(item))||'—',updated:(meta.find(item=>item.startsWith('更新'))||'').replace(/^更新\s*/,'')||'—',facts:PrototypeExtensionDetail.sample(isMcp?'mcp':'skills',name)};
  const headActions=isMcp
    ?'<button class="icon-btn" type="button" data-prototype-action="mcp-edit" title="编辑" aria-label="编辑 '+logEsc(name)+'">'+ICON_EDIT+'</button><button class="icon-btn danger" type="button" data-prototype-action="mcp-delete" title="删除" aria-label="删除 '+logEsc(name)+'">'+ICON_TRASH+'</button>'
    :'<button class="icon-btn" type="button" data-prototype-action="skill-detail-update" title="检查 / 更新" aria-label="检查 / 更新 '+logEsc(name)+'">'+ICON_REFRESH+'</button><button class="icon-btn danger" type="button" data-prototype-action="skill-detail-uninstall" title="卸载" aria-label="卸载 '+logEsc(name)+'">'+ICON_TRASH+'</button>';
  const targetsHTML=[...row.querySelectorAll('.skill-targets .target-icon')].map((button,index)=>{
    const label=button.title||button.getAttribute('aria-label')||'客户端',on=button.getAttribute('aria-checked')==='true',icon=(button.querySelector('use')?.getAttribute('href')||'').replace(/^#/,'');
    return '<li'+(on?' class="on"':'')+'><button class="skill-detail-target" type="button" data-sync-target="'+index+'" aria-pressed="'+on+'" aria-label="'+logEsc(label)+'：'+(on?'已同步，点击关闭同步':'未同步，点击同步')+'">'+(icon?'<svg class="target-svg" aria-hidden="true"><use href="#'+logEsc(icon)+'"/></svg>':'')+'<span>'+logEsc(label)+'</span><em>'+(on?'已同步':'未同步')+'</em></button></li>';
  }).join('');
  window.__extDetailRow=row;
