}

// 目标格子：点一下在「同步 / 关闭同步」之间切换，并同步写回列表那一行的开关。
function toggleExtDetailTarget(button){
  const label=(button.querySelector('span')||{}).textContent?.trim()||'客户端';
  const next=button.getAttribute('aria-pressed')!=='true';
  button.setAttribute('aria-pressed',String(next));
  button.setAttribute('aria-label',label+'：'+(next?'已同步，点击关闭同步':'未同步，点击同步'));
  button.closest('li').classList.toggle('on',next);
  const state=button.querySelector('em');
  if(state) state.textContent=next?'已同步':'未同步';
  const rowButton=(window.__extDetailRow||document).querySelectorAll('.skill-targets .target-icon')[Number(button.dataset.syncTarget)];
  if(rowButton) rowButton.setAttribute('aria-checked',String(next));
  toast('原型模拟：已'+(next?'开启 ':'关闭 ')+label+' 的同步；不写真实客户端配置。');
}

