// read / resolved / deleted 三态显式声明：未读不等于未解决；删除用软删除，保留历史判定依据。
// op / dedupe 为 mock 字段，用于表达 operation_id 与去重键。
let notifications=[
  {id:'external-takeover',kind:'warning',cat:'run',title:'外部 provider 已接管 Codex 配置',detail:'外部应用托管了 ~/.codex/config.toml。该所有权边界属于 OpenCodex CLI 本身；桌面壳只解释影响，不会覆盖外部配置。',time:'10:24',action:'restore',target:'external_takeover',read:false,resolved:false,deleted:false,op:'op_7f3a',dedupe:'takeover:codex-config'},
  {id:'upgrade-available',kind:'warning',cat:'update',title:'OpenCodex 有可用更新',detail:'当前 2.50.0，最新 2.51.0。升级前会先生成备份，并只引导官方 ocx update。',time:'10:18',action:'upgrade',read:false,resolved:false,deleted:false,dedupe:'update:opencodex:2.51.0'},
  {id:'app-update-available',kind:'info',cat:'update',title:'桌面管理器有可用更新',detail:'当前 v0.1.0，最新 v0.1.1。下载校验后重启应用生效，不影响 OpenCodex 代理。',time:'10:16',action:'app-update',read:true,resolved:false,deleted:false,dedupe:'update:app:0.1.1'},
  {id:'sync-connected',kind:'info',cat:'sync',title:'WebDAV 同步连接正常',detail:'最近同步在今天 10:24 完成，所选对象已一致。',time:'10:24',action:'sync',read:true,resolved:true,resolvedAt:'10:24',deleted:false,dedupe:'sync:ok'},
  {id:'sync-partial',kind:'warning',cat:'sync',title:'部分同步未完成',detail:'已更新 3 项，Docs MCP 写入失败；其余内容已完成，可仅重试失败项。',time:'10:22',action:'sync',read:false,resolved:false,deleted:false,op:'op_5c11',dedupe:'sync:failed:op_5c11'},
  {id:'start-failed',kind:'danger',cat:'run',title:'OpenCodex 启动失败',detail:'端口 10100 被占用。建议查看日志或重试启动；未自动重试。',time:'10:02',action:'logs',read:false,resolved:false,deleted:false,op:'op_2a90',dedupe:'start:port-in-use'},
  {id:'env-node-missing',kind:'warning',cat:'system',title:'未检测到 Node.js',detail:'OpenCodex 运行依赖 Node.js；请安装后重新探测。',time:'09:58',action:'settings-installation',read:false,resolved:false,deleted:false,dedupe:'env:node-missing'},
  {id:'auto-clean',kind:'info',cat:'system',title:'通知自动清理已保留 30 天',detail:'已读通知按保留期自动归档；未读与 danger 通知不会被自动删除。',time:'09:40',action:'settings-cleanup',read:true,resolved:true,resolvedAt:'09:40',deleted:false,dedupe:'policy:auto-clean'}
];
// 维护原型事件投影到既有通知中心；已读 / 解决 / 软删除保持原有语义。
window.maintenanceNotificationBridge=(items, registry)=>{
  items.forEach(entry=>{
    const spec=registry.find(item=>item.id===entry.id);
    if(!entry.delivery?.includes('center')) return;
    const id='maintenance:'+entry.uid;
    const old=notifications.find(item=>item.id===id);
    if(old){old.resolved=old.resolved||entry.resolved;old.detail=spec.trigger+' · 累计 '+entry.occurrences+' 次（内存示例）';return;}
    notifications.unshift({id,kind:entry.severity,cat:entry.category,title:spec.trigger,
      detail:spec.id+' · '+entry.object+' · 内存示例；无真实投递',time:'刚刚',
      action:entry.category==='update'?'upgrade':entry.id.startsWith('backup.')?'settings-backup':'logs',
      read:false,resolved:entry.resolved,deleted:false,dedupe:entry.key});
  });
  renderNotifications();renderNotificationHistory();
};
// 通知中心不再提供「未读 / 未解决 / 全部历史」筛选行（用户 2026-09-19 决定取消）；默认展示全部，
// 三态本身仍保留在数据层与条目标签上（已读 ≠ 已解决）。
let notificationState='all'; // unread | unresolved | all
let notificationCat='all';

// 删除用垃圾桶，和扩展/MCP 列表里的删除键保持一致。
const DEL_ICON='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 7h16"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M6 7l1 13h10l1-13"/><path d="M9 7V4h6v3"/></svg>';
// 每个通知表面右上角的「收起」图标。
const MIN_ICON='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 14h6v6"/><path d="M20 10h-6V4"/><path d="M14 10 20 4"/><path d="M10 14 4 20"/></svg>';

// 存活 = 未软删除。未读数量、角标、列表都只从这一个数据源计算，不再有第二处计数。
const liveNotifications=()=>notifications.filter(item=>!item.deleted);
// 已解决即视为处理完毕，不再计入未读。
const unreadCount=()=>liveNotifications().filter(item=>!item.read&&!item.resolved).length;
const unresolvedCount=()=>liveNotifications().filter(item=>!item.resolved).length;
function matchesState(item){
  if(notificationState==='unread') return !item.read&&!item.resolved;
  if(notificationState==='unresolved') return !item.resolved;
  return true;
}
function notificationItemHTML(item,isHistory){
  const tag=item.resolved?'<span class="n-tag">已解决</span>':(item.read?'<span class="n-tag">未解决</span>':'');
  const cls=(isHistory?'history-item':'notification-item')+' '+item.kind+(item.resolved?' resolved':'')+((item.read||item.resolved)?' is-read':'');
  return `<div class="${cls}" data-notification-row="${item.id}">
      <button type="button" class="n-main" data-notification="${item.id}">
        <span class="severity"></span>
        <div><strong>${item.title}${tag}</strong><span>${item.detail}</span></div>
      </button>
      ${isHistory?`<time>${item.time}</time>`:''}
      <div class="n-actions"><button type="button" class="n-del" data-notification-delete="${item.id}" title="删除这条通知" aria-label="删除这条通知">${DEL_ICON}</button></div>
    </div>`;
}
function renderNotifications(){
  const list=document.getElementById('notificationList');
  const dot=document.getElementById('notificationDot');
  const empty=document.getElementById('notificationEmpty');
  if(!list||!dot) return;
  const unread=unreadCount();
  const live=liveNotifications();
  // 分类数量徽标：按分类统计存活通知（不随「未读 / 未解决」筛选变化，表达该类共有多少条）。
  document.querySelectorAll('[data-notification-count]').forEach(badge=>{
    const cat=badge.dataset.notificationCount;
    const n=live.filter(item=>cat==='all'||item.cat===cat).length;
    badge.textContent=String(n);
    badge.hidden=n===0;
  });
  const visible=live.filter(matchesState).filter(item=>notificationCat==='all'||item.cat===notificationCat);
  dot.textContent=String(unread);
  dot.className='notification-dot'+(live.some(item=>item.kind==='danger'&&!item.resolved)?' danger':'')+(unread?' show':'');
  list.innerHTML=visible.map(item=>notificationItemHTML(item,false)).join('');
  if(empty) empty.hidden=visible.length>0;
  const sc=document.getElementById('notificationStateCats');
  if(sc) sc.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.notificationState===notificationState));
  renderNotificationHistory();
}

function renderNotificationHistory(){
  const list=document.getElementById('notificationHistory');
  const meta=document.getElementById('historyMeta');
  if(!list) return;
  const live=liveNotifications();
  if(meta) meta.textContent=`共 ${live.length} 条 · 未读 ${unreadCount()} · 未解决 ${unresolvedCount()} · 保留最近 30 天`;
  list.innerHTML=live.length?live.map(item=>notificationItemHTML(item,true)).join(''):'<div class="notification-empty">暂无通知历史。</div>';
}

function markAllNotificationsRead(){
  liveNotifications().forEach(item=>{item.read=true});
  renderNotifications();
}
function resolveNotification(id){
  const item=notifications.find(entry=>entry.id===id);
  if(!item) return;
  item.read=true;item.resolved=true;item.resolvedAt=item.time;
  renderNotifications();
  toast('原型模拟：已标记「'+item.title+'」为已解决。');
}

function softDeleteNotification(item){
  item.deleted=true;clearTask(item.id);window.hideModelSaveNotification?.(item.id);
}
// 单条删除：软删除，通知中心与通知历史共用同一份数据。
function deleteNotification(id){
  const item=notifications.find(entry=>entry.id===id);
  if(!item) return;
  softDeleteNotification(item);
  renderNotifications();
  closeNotificationPanel();
  toast('原型模拟：已删除通知「'+item.title+'」。');
}
function closeNotificationPanel(){
  notificationPanel.classList.remove('show');
  notificationBtn.setAttribute('aria-expanded','false');
}
// 通知详情弹窗：正文 + 时间/级别；有可执行动作时给「前往处理」，任何时候都能删除。
function notificationJump(item){
  if(item.action==='restore') return ()=>openRestoreConfirm(item.target);
  if(item.action==='upgrade'||item.action==='app-update') return ()=>openSettingsSection('upgrade');
  if(item.action==='sync') return ()=>openSettingsSection('sync');
  if(item.action==='models') return ()=>setRoute('models');
  // 跳转日志必须同时激活「日志历史」Tab，避免落在通知历史里。
  if(item.action==='logs') return ()=>{setRoute('logs');activateDiagTab('logs');};
  if(item.action==='settings-installation') return ()=>openSettingsSection('installation');
  if(item.action==='settings-backup') return ()=>openSettingsSection('backup');
  if(item.action==='settings-cleanup') return ()=>openSettingsSection('cleanup');
  return null;
}
function activateDiagTab(tab){
  const btn=document.querySelector('[data-diag-tab="'+tab+'"]');
  if(btn) btn.click();
}
function openNotificationDetail(id){
  const item=notifications.find(entry=>entry.id===id);
  if(!item) return;
  if(item.eventId?.startsWith('component.demo.')){window.prototypeNotificationPublisher?.open(item.id);return;}
  if(item.eventId==='overview.demo.notification'){window.prototypeNotificationPublisher?.open(item.id);return;}
  if(item.eventId?.startsWith('sync.')){window.prototypeNotificationPublisher?.open(item.id);return;}
  if(item.eventId==='model.template.external'){window.openExternalTaskNotification?.(item.id);return;}
  if(item.eventId==='model.policy.save'){window.openModelSaveNotification(item.id);return;}
  const kindLabel={warning:'警告',danger:'风险',info:'信息'}[item.kind]||'信息';
  const jump=notificationJump(item);
  closeNotificationPanel();
  const status=item.resolved?('已解决 · '+item.resolvedAt):'未解决';
  const meta='<span class="modal-meta">'+item.time+' · '+kindLabel+' · '+status+
    (item.op?' · op '+item.op:'')+(item.dedupe?' · dedupe '+item.dedupe:'')+'</span>';
  openModal(item.title,
    item.detail+meta,
    jump?'前往处理':'关闭', jump,
    {cancelLabel:'关闭', hideConfirm:!jump, onDelete:()=>deleteNotification(item.id),
     onExtra:item.resolved?null:()=>resolveNotification(item.id), extraLabel:'标记已解决'});
}

document.addEventListener('click',event=>{
  const del=event.target.closest('[data-notification-delete]');
  if(del){ deleteNotification(del.dataset.notificationDelete); return; }
  const item=event.target.closest('[data-notification]');
  if(!item) return;
  const notification=notifications.find(entry=>entry.id===item.dataset.notification);
  if(!notification) return;
  if(!notification.read){
    notification.read=true;
    renderNotifications();
  }
  openNotificationDetail(notification.id);
});

function openModal(title,body,confirmText,handler,opts){
  window.prototypeSelect?.close();
  opts=opts||{};
  modalTitle.textContent=title;
  // 所有原型说明统一进入共享注释层；hideNote为旧调用兼容参数，不再生成正文脚注。
  const modalAnnotationTitle=logEsc(opts.prototypeAnnotation?.title||'弹窗均为演示交互');
