let panelHubOpen=false;
function setPanelHubOpen(next){
  panelHubOpen=next;
  document.getElementById('panelHub')?.classList.toggle('open',next);
  document.getElementById('panelHubToggle')?.setAttribute('aria-expanded',next?'true':'false');
  if(next) requestAnimationFrame(positionPanelHubMenu);
}
function positionPanelHubMenu(){
  const hub=document.getElementById('panelHub');
  const menu=document.getElementById('panelHubMenu');
  if(!hub||!menu) return;
  const frame=hub.closest('.panel-frame')||hub.parentElement;
  const hubRect=hub.getBoundingClientRect();
  const frameRect=frame.getBoundingClientRect();
  const margin=12;
  menu.style.left='auto';menu.style.right='auto';menu.style.top='auto';menu.style.bottom='auto';
  menu.style.maxWidth='';menu.style.maxHeight='';
  menu.style.visibility='hidden';
  const rect=menu.getBoundingClientRect();
  let left=hubRect.left+hubRect.width/2-rect.width/2;
  let top=hubRect.bottom+8;
  if(top+rect.height>frameRect.bottom-margin) top=hubRect.top-rect.height-8;
  if(top<frameRect.top+margin) top=frameRect.top+margin;
  if(left<frameRect.left+margin) left=frameRect.left+margin;
  if(left+rect.width>frameRect.right-margin) left=frameRect.right-rect.width-margin;
  left=Math.max(frameRect.left+margin,Math.min(left,frameRect.right-margin-rect.width));
  top=Math.max(frameRect.top+margin,Math.min(top,frameRect.bottom-margin-rect.height));
  menu.style.left=`${left}px`;
  menu.style.top=`${top}px`;
  menu.style.visibility='';
}
