// 键盘（Enter/Space 触发的 click，detail===0）切换菜单；鼠标轻点由拖拽 IIFE 的 pointerup 处理。
document.getElementById('panelHubToggle')?.addEventListener('click',event=>{
  if(event.detail>0) return;
  setPanelHubOpen(!panelHubOpen);
});
document.addEventListener('keydown',event=>{
