});
(function initPanelHubDrag(){
  const hub=document.getElementById('panelHub');
  const handle=document.getElementById('panelHubToggle');
  if(!hub||!handle) return;
  let dragging=false,moved=false,startX=0,startY=0,originX=0,originY=0;
  handle.addEventListener('pointerdown',event=>{
    if(event.pointerType!=='mouse') return;
    event.preventDefault();
    handle.setPointerCapture(event.pointerId);
    dragging=true;moved=false;
    const rect=hub.getBoundingClientRect();const parent=hub.parentElement.getBoundingClientRect();
    originX=rect.left-parent.left;originY=rect.top-parent.top;
    startX=event.clientX;startY=event.clientY;
  });
  handle.addEventListener('pointermove',event=>{
    if(!dragging) return;
    const dx=event.clientX-startX,dy=event.clientY-startY;
    if(!moved&&(Math.abs(dx)>2||Math.abs(dy)>2)){moved=true;setPanelHubOpen(false);}
    if(!moved) return;
    const parent=hub.parentElement.getBoundingClientRect();
    const rect=hub.getBoundingClientRect();
    const x=Math.min(Math.max(12,originX+dx),parent.width-rect.width-12);
    const y=Math.min(Math.max(12,originY+dy),parent.height-rect.height-12);
    hub.style.left=x+'px';hub.style.top=y+'px';hub.style.bottom='auto';hub.style.right='auto';
  });
  handle.addEventListener('pointerup',event=>{
    if(!dragging) return;
    dragging=false;
    if(event.pointerType!=='mouse') return;
    // 轻点（未移动）= 切换菜单；拖动过 = 不切换。
    if(!moved) setPanelHubOpen(!panelHubOpen);
  });
  handle.addEventListener('pointercancel',()=>{dragging=false;moved=false;});
})();
