// ── WebDAV 卡片：按「配置 / 连接」状态渲染内容与动作（不渲染无解释的禁用态）──
// 「未配置」是初始态：卡片主体说明未配置，动作区只留一颗「配置 WebDAV」主按钮，右上角 ⋯ 仍可进设置。
// 概览与同步页共用预览，单一新版快照来源在弹窗内说明。
// 未配置 / 未连接 / 连接失败：线上版本只写「—」，不画点、不写方向词。
const webdavStates={
  unconfigured:{tag:'未配置',conn:'未配置',remote:'—',dir:null,
    actions:[['配置 WebDAV','btn primary','test-webdav']]},
  disconnected:{tag:'未连接',conn:'未连接',remote:'—',dir:null,
    actions:[['同步','btn primary','sync']]},
  'local-newer':{tag:'有更新',conn:'已连接',remote:'09:30',dir:['ok','有更新'],
    actions:[['同步','btn primary','sync']]},
  'remote-newer':{tag:'有更新',conn:'已连接',remote:'09:30',dir:['ok','有更新'],
    actions:[['同步','btn primary','sync']]},
  ready:{tag:'有更新',conn:'已连接',remote:'09:30',dir:['ok','有更新'],
    actions:[['同步','btn primary','sync']]},
  syncing:{tag:'同步中',conn:'已连接',remote:'11:02',dir:['info','同步中'],
    actions:[['同步中…','btn primary','sync']]},
  synced:{tag:'已同步',conn:'已连接',remote:'11:02',dir:['idle','已一致'],
    actions:[['同步','btn primary','sync']]},
  error:{tag:'连接失败',conn:'连接失败',remote:'—',dir:null,
    actions:[['重试连接','btn primary','test-webdav']]},
  partial:{tag:'部分完成',conn:'已连接',remote:'11:02',dir:['warn','未完成'],
    actions:[['同步','btn primary','sync'],['查看结果','btn ghost','sync-result']]},
};
let webdavState='unconfigured';
function renderWebdav(state){
  state=({'pending-upload':'local-newer','pending-download':'remote-newer',bidirectional:'ready'})[state]||state;
  webdavState=webdavStates[state]?state:'unconfigured';
  const el=id=>document.getElementById(id);
  // 概览 WebDAV 卡片的宿主是 #syncActions/#syncConn（历史 id #syncCard 已不存在）；
  // 之前这里早退导致整个 WebDAV 状态测试器「点不动」。
  if(!el('syncActions')) return;
  const cfg=webdavStates[webdavState];
  el('syncTag').textContent=cfg.tag;
  el('syncConn').textContent=cfg.conn;
  el('syncRemoteTime').textContent=cfg.remote;
  const dot=el('syncDirection'),sep=el('syncSep'),text=el('syncDirectionText');
  if(cfg.dir){
    dot.hidden=false;sep.hidden=false;text.hidden=false;
    dot.className='ov-state-dot is-'+cfg.dir[0];
    text.className='ov-state-text is-'+cfg.dir[0];
    text.textContent=cfg.dir[1];
  }else{
    dot.hidden=true;sep.hidden=true;text.hidden=true;text.textContent='';
  }
  el('syncActions').innerHTML=cfg.actions.map(([label,cls,act])=>
    `<button class="${cls}" data-prototype-action="${act}">${label}</button>`).join('');
  document.querySelectorAll('#webdavStates button').forEach(b=>
    b.classList.toggle('active',b.dataset.webdav===webdavState));
  el('syncActions').querySelectorAll('button').forEach(button=>button.disabled=webdavState==='syncing');
}
window.renderWebdav=renderWebdav;
document.querySelectorAll('#webdavStates button').forEach(button=>{
  button.addEventListener('click',()=>{const state=button.dataset.webdav;window.syncPrototype?.setScenario(state==='local-newer'?'upload':state==='synced'?'same':state==='partial'?'partial':state==='error'?'network-error':'normal');renderWebdav(state);});
});
document.addEventListener('prototype:sync-started',event=>{if(event.detail?.mode==='webdav')renderWebdav('syncing');});
// ── 文件同步卡片：只显示最近一次导入 / 导出的事实（时间 + 项数）──
document.addEventListener('prototype:sync-activity',event=>{
  const detail=event.detail||{};
  if(detail.kind==='sync'){
    // 同步完成后卡片直接回到「已一致」，线上版本时间用这次同步的时间。
    if(webdavState!=='unconfigured'&&webdavState!=='disconnected'&&webdavState!=='error') renderWebdav(detail.complete===false?'partial':'synced');
    const remote=document.getElementById('syncRemoteTime');
    if(remote&&webdavState!=='unconfigured'&&webdavState!=='disconnected') remote.textContent=detail.remoteTime?.slice(11,16)||detail.time;
    return;
  }
  const node=document.getElementById(detail.kind==='import'?'overviewImportActivity':detail.kind==='export'?'overviewExportActivity':'');
  if(!node) return;
  const count=Number(detail.count)||0;
  node.textContent=detail.time+' · '+count+' 项'+(detail.complete===false?' · 未完成':'');
});

// ── 主题：外壳与内嵌面板共用同一个取值（localStorage 键 ocx-theme）──
// 面板不再保存自己的主题；首帧由 URL 参数给出，切换由 postMessage 实时同步。
let themeSetting='system';
function resolvedTheme(){
  if(themeSetting==='light'||themeSetting==='dark') return themeSetting;
  try{return window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}catch(e){return 'light'}
}
function panelFrameUrl(cacheBust){
  const frame=document.getElementById('panelReal');
  const proxy=(frame&&frame.dataset.proxy)||'';
  try{
    const url=new URL(proxy,location.href);
    url.searchParams.set('theme',resolvedTheme());
    if(cacheBust) url.searchParams.set('reload',String(cacheBust));
    return url.href;
  }catch(e){return ''}
}
function syncPanelTheme(){
  const frame=document.getElementById('panelReal');
  if(!frame||!frame.contentWindow) return;
  const theme=resolvedTheme();
  try{frame.contentWindow.postMessage({type:'ocx-theme',theme},'*')}catch(e){}
}
document.getElementById('panelReal').addEventListener('load',syncPanelTheme);
function applyTheme(theme){
  themeSetting=['light','dark','system'].includes(theme)?theme:'system';
  try{window.localStorage.setItem('ocx-theme',themeSetting)}catch(e){}
  document.documentElement.setAttribute('data-theme',resolvedTheme());
  syncPanelTheme();
  document.querySelectorAll('#themeSeg button').forEach(button=>{
    button.classList.toggle('active',button.dataset.themeOption===themeSetting);
  });
}
document.querySelectorAll('#themeSeg button').forEach(button=>{
  button.addEventListener('click',()=>applyTheme(button.dataset.themeOption));
});
window.applyTheme=applyTheme;
// 系统主题变化时只有「跟随系统」需要重算，其它取值不受影响。
try{
  window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{
    if(themeSetting==='system') applyTheme('system');
  });
}catch(e){}

// ── 界面缩放：设置中的滑块同步作用于外壳与内嵌面板，验证同一缩放因子观感 ──
// 真实 Tauri 实现中，面板侧应调用 setZoomFactor()，而不是 CSS 拉伸 iframe。
function applyInterfaceScale(scale){
  const value=Math.min(200,Math.max(50,Math.round(Number(scale)||100)));
  document.documentElement.style.setProperty('--panel-zoom',String(value/100));
  const label=document.getElementById('panelScaleLabel');
  const text=document.getElementById('panelScaleText');
  if(text) text.textContent='界面 '+value+'%';
  if(label){
    label.hidden=value===100;
    label.style.transform=value>100?'scale(1.04)':(value<100?'scale(.96)':'none');
  }
  const panelReadout=document.getElementById('panelScaleReadout');
  if(panelReadout) panelReadout.textContent=value+'%';
  const panelBadge=document.getElementById('panelScaleBadge');
  if(panelBadge){
    panelBadge.textContent=value+'%';
    if(panelHubOpen) positionPanelHubMenu();
  }
  const slider=document.getElementById('interfaceScaleRange');
  if(slider && slider.value!==String(value)) slider.value=String(value);
  const settingReadout=document.getElementById('interfaceScaleReadout');
  if(settingReadout) settingReadout.value=String(value);
  document.querySelectorAll('.range-tick').forEach(tick=>{
    const active=Number(tick.dataset.scale)===value;
    tick.classList.toggle('active',active);
    tick.setAttribute('aria-pressed',String(active));
  });
}
window.applyInterfaceScale=applyInterfaceScale;
document.getElementById('interfaceScaleRange').addEventListener('input',event=>{
  applyInterfaceScale(event.target.value);
});
document.querySelectorAll('.range-tick').forEach(tick=>{
  tick.addEventListener('click',()=>applyInterfaceScale(tick.dataset.scale));
});
document.getElementById('interfaceScaleReadout').addEventListener('input',event=>{
  const raw=event.target.value;
  if(raw==='') return;
  const parsed=Number(raw);
  if(Number.isFinite(parsed)) applyInterfaceScale(parsed);
});
document.getElementById('interfaceScaleReadout').addEventListener('change',event=>{
  applyInterfaceScale(event.target.value);
});

