function sysPickerParent(path){
  if(path==='~') return null;
  const cut=path.lastIndexOf('/');
  return cut<=0?null:path.slice(0,cut);
}

function sysPickerActivePlace(){
  const path=window.__sysPickerPath;
  return SYS_PLACES.filter(place=>path===place.path||path.startsWith(place.path+'/'))
    .sort((a,b)=>b.path.length-a.path.length)[0];
}

function sysPickerRender(){
  const path=window.__sysPickerPath;
  const dirs=SYS_MOCK_FS[path]||[];
  const crumbs=document.getElementById('sysPickerCrumbs');
  if(crumbs) crumbs.textContent=path;
  const list=document.getElementById('sysPickerList');
  if(list){
    list.innerHTML=dirs.length
      ? dirs.map(name=>{
          const child=path+'/'+name;
          const count=SYS_MOCK_SKILL_COUNT[child];
          const known=child in SYS_MOCK_FS;
          const note=count?count+' 个 Skill':(known?(SYS_MOCK_FS[child].length?'可展开':'空文件夹'):'');
          return '<button type="button" class="sysdlg-row" data-dir="'+child+'" onclick="sysPickerEnter(this.dataset.dir)">'+
            SYS_FOLDER_ICON+'<span>'+name+'</span><em>'+note+'</em></button>';
        }).join('')
      : '<div class="sysdlg-empty">该文件夹为空；可直接选择它作为源目录。</div>';
  }
  const pathEl=document.getElementById('sysPickerPath');
  if(pathEl) pathEl.textContent=path;
  const skills=SYS_MOCK_SKILL_COUNT[path];
  const hint=document.getElementById('sysPickerHint');
  if(hint) hint.textContent=skills?('检测到 '+skills+' 个 Skill'):'未检测到 SKILL.md（仍可选择）';
  const active=sysPickerActivePlace();
  document.querySelectorAll('.sysdlg-place').forEach(el=>{
    el.classList.toggle('active',!!active&&el.dataset.place===active.path);
  });
  window.__skillsSourcePick=path;
}

function sysPickerEnter(path){
  if(!(path in SYS_MOCK_FS)){ toast('原型模拟：文件夹不存在或不可读 —— '+path); return; }
  window.__sysPickerPath=path;
  sysPickerRender();
}

function sysPickerPlace(path){
