// 公共通知宿主统一挂倒计时；业务页仍只发布已登记事件。
function notificationTone(kind,fallback='info'){
  return ({success:'success',error:'error',danger:'error',warning:'warning',warn:'warning',info:'info',neutral:'neutral'})[kind]||fallback;
}
function toast(msg,opts){
  opts=opts||{};
  const el=document.getElementById('toastEl');
  window.NotificationMotion.cancel(el);
  window.NotificationCountdown.get(el)?.destroy();
  const useCard=!!opts.kind||document.body.classList.contains('notif-mode');
  if(useCard){
    const kind=opts.kind||'success';
    el.className='toast k-card k-'+kind;
    el.innerHTML='<div class="toast-txt"><b>'+(opts.title||msg)+'</b>'+(opts.detail?'<span>'+opts.detail+'</span>':'')+'</div>'+(opts.action?'<button type="button" class="toast-act">'+opts.action+'</button>':'')+'<button type="button" class="notify-min" data-collapse="toast" title="收起到铃铛" aria-label="收起到铃铛">'+MIN_ICON+'</button>';
  }else{
    el.className='toast';
    el.textContent=msg;
  }
  el.classList.add('show');
  clearTimeout(window.__toastTimer);
  const duration=opts.duration||(opts.kind==='error'?5200:2200);
  window.__toastTimer=null;
  window.NotificationCountdown.mount(el,{durationMs:duration,tone:notificationTone(opts.kind,'success'),onElapsed:()=>collapseToBell(el,()=>{el.classList.remove('show');syncNotifHost();})});
  syncNotifHost();
}

/* ==========================================================================
   通知与反馈专题 · 原型专用演示驱动
   在真实软件界面上演出六类渠道；不写配置、不调用真实命令，仅切 mock 投影。
   ========================================================================== */
/* 时效：终止态 8 秒后自动收起（收起不是删除），同屏最多 3 张，同类操作合并成一张。
   与软件 apps/desktop/ui/src/app/feedback/tasks.ts 同一套口径（0.2.12）。 */
const TASK_TERMINAL_TTL=8000, TASK_MAX_VISIBLE=3;
const taskTimers=new Map();
function taskKeyOf(cfg){return cfg.mergeKey||cfg.notificationId||'';}
function cancelTaskCountdown(key){taskTimers.get(key)?.destroy();taskTimers.delete(key);}
function scheduleTaskCollapse(card,tone){
  const key=card.dataset.taskNotification||'';
  if(key)cancelTaskCountdown(key);
  const timer=window.NotificationCountdown.mount(card,{durationMs:TASK_TERMINAL_TTL,tone:notificationTone(tone),onElapsed:()=>{
    if(key){taskTimers.delete(key);if(key.startsWith('component-demo:'))window.prototypeNotificationPublisher?.hide(key);else window.hideModelSaveNotification?.(key);}
    collapseToBell(card,()=>{card.remove();syncNotifHost();});
  }});
  if(key)taskTimers.set(key,timer);
}
/* 超出同屏上限时先收起（移除）最老的已完成卡，运行中的不删。 */
function pretaskBudget(host,keep){
  const cards=[...host.querySelectorAll('.task-card')];
  if(cards.length<keep) return;
  const surplus=cards.length-keep+1;
  let removed=0;
  for(const card of cards){
    if(removed>=surplus) break;
    if(card.classList.contains('is-complete')){cancelTaskCountdown(card.dataset.taskNotification||'');window.NotificationCountdown.get(card)?.destroy();card.remove();removed++;}
  }
  /* 全都还在跑时按最老的收起（运行不受影响，只是不再占屏）。 */
  for(const card of [...host.querySelectorAll('.task-card')]){
    if(removed>=surplus) break;
    cancelTaskCountdown(card.dataset.taskNotification||'');window.NotificationCountdown.get(card)?.destroy();card.remove();removed++;
  }
}
function showTask(cfg){
  const host=document.getElementById('taskHost');
  const steps=cfg.steps.map(s=>'<li class="'+logEsc(s[1])+'"><span class="mk">'+(s[1]==='done'?'✓':'')+'</span>'+logEsc(s[0])+'</li>').join('');
  const acts=(cfg.acts||[]).map(a=>{const arr=Array.isArray(a)?a:[a,''];return [arr[0],!arr[1]||arr[1]==='generic'?/取消/.test(arr[0])?'cancel':/后台/.test(arr[0])?'background':'generic':arr[1]];});
  const mark=cfg.running===false?(cfg.kind==='danger'?'!':cfg.kind==='warning'?'!':cfg.kind==='neutral'?'−':'✓'):null;
  const key=cfg.notificationId||'';
  const markup='<div class="task-card'+(cfg.running===false?' is-complete':'')+'"'+(key?' data-task-notification="'+logEsc(key)+'"':'')+'><div class="tc-head">'+(mark?'<span class="tc-result '+logEsc(cfg.kind||'info')+'">'+mark+'</span>':'<span class="tc-spin"></span>')+'<h4>'+logEsc(cfg.title)+'</h4>'+
    '<button type="button" class="notify-min" data-collapse="task" title="收起到铃铛" aria-label="收起到铃铛">'+MIN_ICON+'</button></div>'+
    (cfg.phase?'<p class="tc-phase">'+logEsc(cfg.phase)+'</p>':'')+(steps?'<ul class="task-steps">'+steps+'</ul>':'')+
    (acts.length?'<div class="tc-acts">'+acts.map((a,i)=>'<button type="button" class="btn'+(a[1]==='cancel'?' cancel':(i?' ghost':''))+'" data-task-act="'+logEsc(a[1])+'" data-task-label="'+logEsc(a[0])+'">'+logEsc(a[0])+'</button>').join('')+'</div>':'')+'</div>';
  const mergeKey=taskKeyOf(cfg);
  const existing=[...host.querySelectorAll('.task-card')].find(card=>(card.dataset.taskNotification||'')===key);
  if(existing){
    window.NotificationMotion.cancel(existing);
    cancelTaskCountdown(key);
    window.NotificationCountdown.get(existing)?.destroy();
    existing.outerHTML=markup;
  }else{
    /* 同类合并：把上一次已终止的同类卡并成「第 N 次」。 */
    if(cfg.mergeKind){
      const same=[...host.querySelectorAll('.task-card')].filter(card=>card.dataset.taskMergeKind===cfg.mergeKind);
      const last=same[same.length-1];
      if(last&&last.classList.contains('is-complete')){
        const count=(Number(last.dataset.taskCount||'1')||1)+1;
        same.forEach(card=>{cancelTaskCountdown(card.dataset.taskNotification||'');window.NotificationCountdown.get(card)?.destroy();card.remove();});
        pretaskBudget(host,1);
        host.insertAdjacentHTML('beforeend',markup);
        const created=host.lastElementChild;
        created.dataset.taskMergeKind=cfg.mergeKind;
        created.dataset.taskCount=String(count);
        if(count>1)created.insertAdjacentHTML('beforeend','<p class="tc-phase">第 '+count+' 次</p>');
        if(cfg.running===false)scheduleTaskCollapse(created,cfg.kind);
        if(!key)host.dataset.op=cfg.op||'';
        host.classList.toggle('stacked',document.getElementById('toastEl').classList.contains('show'));
        syncNotifHost();
        return;
      }
    }
    pretaskBudget(host,TASK_MAX_VISIBLE);
    host.insertAdjacentHTML('beforeend',markup);
    if(cfg.mergeKind)host.lastElementChild.dataset.taskMergeKind=cfg.mergeKind;
  }
  const card=(host.querySelector('[data-task-notification="'+key+'"]'))||host.lastElementChild;
  if(card&&cfg.running===false)scheduleTaskCollapse(card,cfg.kind);
  if(card&&cfg.focusAction&&document.getElementById('modalMask')?.style.display!=='flex')card.querySelector('[data-task-act="'+cfg.focusAction+'"]')?.focus({preventScroll:true});
  if(!key)host.dataset.op=cfg.op||'';
  host.classList.toggle('stacked',document.getElementById('toastEl').classList.contains('show'));
  syncNotifHost();
}
function clearTask(notificationId=''){
  const host=document.getElementById('taskHost');
  cancelTaskCountdown(notificationId);
  if(host)window.NotificationMotion.reflow(()=>[...host.querySelectorAll('.task-card')].filter(card=>(card.dataset.taskNotification||'')===notificationId).forEach(card=>{window.NotificationMotion.cancel(card);window.NotificationCountdown.get(card)?.destroy();card.remove();}));
  syncNotifHost();
}
// 模型保存注册到既有通知实体及壳层任务宿主；收起仅是视图状态，不取消任务或解决通知。
const modelSaveHidden=new Set();
const MODEL_SAVE_PHASES=['备份','原子写入'];
const MODEL_SAVE_STATES={
  running:['正在保存模型配置','info',false],
  written:['已写入','success',true],
  completed:['已写入','success',true],
  failed:['模型配置保存失败','danger',false],
  stopped:['模型配置保存已取消','info',true],
  superseded:['已由后续保存替代','info',true]
};
function renderModelSaveTask(item,focus=false){
  if(item.deleted||modelSaveHidden.has(item.id)||['completed','superseded'].includes(item.modelSave.state))return;
  const task=item.modelSave,active=window.modelPrototype?.state().operation?.id===task.id;
  if(!active)return;
  const running=task.state==='running',failed=task.state==='failed',written=task.state==='written';
  const completed=failed?Math.max(0,task.step-1):task.step;
  const steps=written?[]:MODEL_SAVE_PHASES.map((label,index)=>[label,index<completed?'done':running&&index===task.step?'active':failed&&index===completed?'failed':'pending']);
  const acts=running?[['取消保存','model-stop']]:written?[['立即重启 Codex','model-restart'],['稍后','model-later']]:[];
  showTask({notificationId:item.id,title:item.title,phase:item.detail,steps,acts,running,kind:task.state==='stopped'?'neutral':item.kind,focusAction:focus&&written?'model-restart':''});
}
window.hideModelSaveNotification=id=>{if(id?.startsWith('model-policy-save:'))modelSaveHidden.add(id);};
window.openModelSaveNotification=id=>{
  const item=notifications.find(n=>n.id===id&&!n.deleted&&n.eventId==='model.policy.save');if(!item)return;
  item.read=true;closeNotificationPanel();renderNotifications();
  if(['completed','superseded'].includes(item.modelSave.state))return;
  modelSaveHidden.delete(id);renderModelSaveTask(item,true);
};
// 保存确认被拦下（基准变化 / 待确认编辑 / 超限 / 校验错误）：登记为通知，草稿保留。
window.modelSaveBlockedBridge=function(payload){
  const spec=window.MaintenanceEvents.events.find(event=>event.id==='model.policy.save.blocked');
  const reason=typeof payload?.reason==='string'&&payload.reason?payload.reason:'保存未写入，草稿保留';
  const key='model-policy-save-blocked';
  let item=notifications.find(entry=>entry.id===key);
  if(item?.deleted)item=null;
  if(!item){item={id:key,eventId:spec.id,cat:spec.category,op:key,dedupe:key,read:false,resolved:false,deleted:false};notifications.unshift(item);}
  if(item.detail===reason&&item.read&&!item.resolved)return key;
  Object.assign(item,{kind:'warning',title:'模型配置未保存',detail:reason+'；草稿保留，可回到模型配置重新核对。',action:'models',time:clockLabel(),read:false,resolved:false});
  delete item.resolvedAt;
  renderNotifications();toast('未保存：'+reason);
  return key;
};
window.modelSaveNotificationBridge=function(snapshot){
  const spec=window.MaintenanceEvents.events.find(event=>event.id==='model.policy.save');
  if(!snapshot){
    notifications.filter(item=>item.eventId===spec.id).forEach(item=>{modelSaveHidden.add(item.id);clearTask(item.id);});
    renderNotifications();return;
  }
  const {id,status}=snapshot,step=Math.min(snapshot.step,2);
  if(!Number.isSafeInteger(id)||!Number.isInteger(snapshot.step)||snapshot.step<0||snapshot.step>5)return;
  // 旧成功 / 已确认 / 待重启只保留完成历史，不恢复旧任务或客户端核对。
  const state=['success','confirmed','pending','verified'].includes(status)?'completed':['timeout','uncertain'].includes(status)?'failed':status;
  if(!Object.hasOwn(MODEL_SAVE_STATES,state))return;
  const key='model-policy-save:'+id,revision=state+':'+step;
  let item=notifications.find(entry=>entry.id===key);
  if(item?.modelSave.revision===revision||item?.modelSave.state==='completed')return;
  const [title,kind,resolved]=MODEL_SAVE_STATES[state];
  const detail=state==='running'?'全渠道保存 · '+MODEL_SAVE_PHASES[Math.min(step,1)]+'…':state==='failed'?'保存未完成，原文件与草稿保留。':state==='stopped'?'未写入，草稿保留。':'';
  if(!item){
    notifications.filter(other=>other.eventId===spec.id).forEach(other=>{
      modelSaveHidden.add(other.id);clearTask(other.id);
      if(other.modelSave.state==='written')Object.assign(other,{title:'已写入',detail:'',read:true,resolved:true,modelSave:{...other.modelSave,state:'completed'}});
    });
    item={id:key,eventId:spec.id,cat:spec.category,op:key,dedupe:key,read:false,resolved:false,deleted:false};notifications.unshift(item);
  }else if(item.modelSave.state!==state)item.read=false;
  Object.assign(item,{title,kind,detail,resolved,time:clockLabel(),modelSave:{id,state,step,revision}});
  if(resolved)item.resolvedAt=item.time;
  if(state==='completed'){item.read=true;modelSaveHidden.add(key);clearTask(key);}
  renderNotifications();renderModelSaveTask(item,state==='written');
};
