/* 通知位置预览：只在软件窗口内，先给「顶部 / 右上」两个候选（未定稿）。 */
const NOTIF_POS_DEFAULT='win-tr';
const notifHostEl=document.getElementById('notifHost');
const nToastEl=document.getElementById('toastEl');
const nTaskEl=document.getElementById('taskHost');
function notifPos(){return document.body.dataset.notifPos||NOTIF_POS_DEFAULT;}
function positionNotifHost(){
  const host=notifHostEl;
  if(!host)return;
  const gap=16,s=host.style,win=document.querySelector('.window');
  s.left='auto';s.right='auto';s.top='auto';s.bottom='auto';s.removeProperty('--host-max');
  if(!win)return;
  const r=win.getBoundingClientRect();
  const bell=document.getElementById('notificationBtn')?.getBoundingClientRect();
  let top=Math.max(gap,r.top+40,bell?.height?bell.bottom+12:0);
  // 通知中心面板与 Toast / 任务卡都在窗口右上；面板展开时把浮层顺序下移，避免互相压盖。
  const panel=document.getElementById('notificationPanel');
  if(panel&&panel.classList.contains('show')&&host.offsetHeight>0){
    const candidate=Math.round(panel.getBoundingClientRect().bottom)+12;
    if(candidate+host.offsetHeight<=r.bottom-16) top=Math.max(top,candidate);
  }
  s.top=top+'px';
  s.setProperty('--host-max',Math.max(160,Math.round(r.bottom-16-top))+'px');
  if(notifPos()==='win-top'){
    const w=host.getBoundingClientRect().width;
    s.left=Math.max(gap,r.left+(r.width-w)/2)+'px';
  }else{
    s.right=Math.max(gap,window.innerWidth-r.right+gap)+'px';
  }
}
function syncNotifHost(){positionNotifHost();requestAnimationFrame(positionNotifHost);}
// 面板开合或浮层内容变化时自动重算位置；只观察 class/子节点，不观察自身 style，避免定位写回触发死循环。
