  const relayoutNotifHost=()=>positionNotifHost();
  const nPanelEl=document.getElementById('notificationPanel');
  if(nPanelEl) new MutationObserver(relayoutNotifHost).observe(nPanelEl,{attributes:true,attributeFilter:['class']});
  if(notifHostEl) new MutationObserver(relayoutNotifHost).observe(notifHostEl,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});
}catch(e){}
