function ensureDemoNotifications(){
  demoExtraNotifications.forEach(n=>{if(!notifications.some(x=>x.id===n.id))notifications.push(n)});
}
function openNotif(id){
  ensureDemoNotifications();
  notifications.forEach(n=>{if(n.id===id)n.read=false});
  notificationCat='all';
  document.querySelectorAll('[data-notification-cat]').forEach(b=>b.classList.toggle('active',b.dataset.notificationCat==='all'));
  renderNotifications();
  notificationPanel.classList.add('show');
  notificationBtn.setAttribute('aria-expanded','true');
  document.querySelectorAll('.notification-item.hl,.history-item.hl').forEach(el=>el.classList.remove('hl'));
  document.querySelectorAll('[data-notification="'+id+'"]').forEach(el=>{el.classList.add('hl');try{el.scrollIntoView({block:'nearest'})}catch(e){}});
  syncNotifHost();
}
function closeNotifDemo(){
  notificationPanel.classList.remove('show');
  notificationBtn.setAttribute('aria-expanded','false');
  document.querySelectorAll('.notification-item.hl,.history-item.hl').forEach(el=>el.classList.remove('hl'));
  syncNotifHost();
}

