let notifCat='all';
let curNotifIdx=-1;

function renderNotifLauncher(){
  const cats=document.getElementById('notifCats');
  const list=document.getElementById('notifScn');
  cats.innerHTML='<button type="button" data-ncat="all" class="'+(notifCat==='all'?'active':'')+'">全部</button>'+
    NOTIF_ORDER.map(k=>'<button type="button" data-ncat="'+k+'" class="'+(notifCat===k?'active':'')+'">'+NOTIF_CATS[k].name+'</button>').join('');
  cats.querySelectorAll('button').forEach(b=>b.onclick=()=>{notifCat=b.dataset.ncat;renderNotifLauncher();});
  let html='';
  NOTIF_ORDER.forEach(k=>{
    if(notifCat!=='all'&&notifCat!==k)return;
    const rows=NOTIF_SCEN.map((s,i)=>({s,i})).filter(o=>o.s[0]===k);
    if(!rows.length)return;
    html+='<div class="ns-cat">'+NOTIF_CATS[k].name+' · '+rows.length+'</div>';
    rows.forEach(({s,i})=>{html+='<button type="button" data-nidx="'+i+'" class="'+(i===curNotifIdx?'active':'')+'">'+s[1]+'</button>';});
  });
  list.innerHTML=html;
  list.querySelectorAll('button').forEach(b=>b.onclick=()=>runNotifScenario(Number(b.dataset.nidx)));
}

function renderNotifHint(entry){
  const hint=document.getElementById('notifHint');
  if(!entry){hint.textContent='选择一条场景，界面会切到对应路由并演出该渠道的真实效果。';return;}
  const s=entry.s;
  hint.innerHTML='<b>'+s[2]+'</b> · 主展示：'+s[3]+'<br>辅助：'+(s[4]||'—')+' · 默认不自动出现：<span style="color:#b91c1c">'+(s[5]||'—')+'</span><br>终态：'+(s[6]||'—')+'<br>'+(s[7]||'');
}

function runNotifScenario(i){
  const s=NOTIF_SCEN[i]; if(!s)return;
  const run=s[8]||{};
  curNotifIdx=i;
  enterNotifMode();
  // 先复位上一次演示的浮层
  closeModal(); closeNotifDemo(); clearTask();
  document.getElementById('toastEl').classList.remove('show');
  // 路由与 mock 投影
  if(run.env) setEnv(run.env);
  if(run.route) setRoute(run.route,true);
  if(run.section&&typeof showSettingsSection==='function') showSettingsSection(run.section);
  if(run.tab){setTimeout(()=>{const t=document.querySelector('[data-ext-tab="'+run.tab+'"]')||document.querySelector('[data-diag-tab="'+run.tab+'"]');if(t)t.click();},0);}
  if(run.webdav&&typeof renderWebdav==='function') renderWebdav(run.webdav);
  if(run.state) setState(run.state);
  if(run.emptyNotif){notifications.forEach(n=>n.read=true);renderNotifications();}
  // 浮层
  if(run.task) showTask(run.task);
  if(run.toast) toast(run.toast.title,run.toast);
  if(run.notif) openNotif(run.notif);
  if(run.modal){
    openModal(run.modal.title,
      (run.modal.warning?'<p class="modal-warning"><strong>警告：</strong><span>'+run.modal.warning+'</span></p>':'')+
      '<p class="modal-lead">'+run.modal.body+'</p>'+
      (run.modal.facts?'<div class="modal-facts">'+run.modal.facts.map(f=>'<div><b>'+f[0]+'</b><span>'+f[1]+'</span></div>').join('')+'</div>':''),
      run.modal.confirm, ()=>{}, {cancelLabel:'取消'});
    document.getElementById('modal').classList.toggle('modal-wide',!!run.modal.wide);
  }else{
    document.getElementById('modal').classList.remove('modal-wide');
  }
  // 同步专题沿实际共享窗口与内存流程，不另造比较或覆盖确认。
  if(run.sync){
    if(run.syncScenario) window.syncPrototype?.setScenario(run.syncScenario);
    window.syncPrototype?.open(run.sync);
  }
  if(run.scroll){setTimeout(()=>{const el=document.getElementById(run.scroll);if(el)el.scrollIntoView({block:'center'});},30);}
  renderNotifLauncher();
  renderNotifHint({cat:s[0],s:s,run:run});
  syncLaunchActive();
  syncNotifHost();
}

// 通知宿主是全局壳层，Toast / 任务卡始终可用；notif-mode 只表示「通知专题」这个场景切换器处于打开状态。
function enterNotifMode(){document.body.classList.add('notif-mode');syncNotifHost();}
function exitNotifMode(){
  document.body.classList.remove('notif-mode');
  closeNotifDemo();
  nToastEl.classList.remove('show');
}
function closeNotifPanelSafe(){
  const p=document.getElementById('notificationPanel');
  if(p){p.classList.remove('show');document.querySelectorAll('.notification-item.hl,.history-item.hl').forEach(el=>el.classList.remove('hl'));}
  const b=document.getElementById('notificationBtn');
  if(b)b.setAttribute('aria-expanded','false');
}
// 「通知与反馈」是独立菜单：进入后只显示专题，不与概览/其他卡片混排。
function openNotifMenu(){
  curNotifIdx=-1;
  exitNotifMode(); enterNotifMode();
  renderNotifLauncher(); renderNotifHint(null);
  setEnv('ready'); setState('stopped'); setRoute('overview',true);
  syncLaunchActive();
}
function resetNotifDemo(){
  curNotifIdx=-1;
  closeModal(); closeNotifDemo(); clearTask();
  document.getElementById('toastEl').classList.remove('show');
  setEnv('ready'); setState('stopped'); setRoute('overview',true);
  renderNotifLauncher(); renderNotifHint(null);
}

function syncLaunchActive(){
  const inNotif=document.body.classList.contains('notif-mode');
  const inWindows=document.body.classList.contains('windows-mode');
  const inComponents=inNotif||inWindows||['components','model-picker','tray','annotations'].includes(currentRoute);
  const map={overview:'overview',panel:'panel',models:'models',conversations:'conversations',extensions:'extensions',logs:'logs',settings:'settings',sync:'sync','connection-map':'connection-map'};
  document.querySelectorAll('#launchGrid button').forEach(b=>{
    const on=b.dataset.launch==='components'?inComponents:(!inNotif&&!inWindows&&map[currentRoute]===b.dataset.launch);
    b.classList.toggle('active',on);
  });
}

document.getElementById('launchGrid').querySelectorAll('button').forEach(b=>{
  b.onclick=()=>{
    if(b.dataset.launch==='windows'){window.windowsPrototype.enter();return;}
    window.windowsPrototype?.exit();
    if(b.dataset.launch==='notify'){openNotifMenu();return;}
    exitNotifMode();setRoute(b.dataset.launch);syncLaunchActive();
  };
});
document.getElementById('notifReset').onclick=()=>resetNotifDemo();
document.getElementById('notifExit').onclick=()=>{exitNotifMode();setRoute('overview',true);syncLaunchActive();};
document.addEventListener('click',event=>{
  const nav=event.target.closest('.nav button[data-route]');
  if(!nav)return;
  exitNotifMode();
  setTimeout(syncLaunchActive,0);
});
renderNotifLauncher();renderNotifHint(null);
