  if(p) setNotifPos(p);
}catch(e){}
setTimeout(syncLaunchActive,0);
// 便于对照评审：?notif=N 直达某条专题场景（沿用同一套 mock 投影）。
try{
  const nq=new URLSearchParams(location.search);
  const nidx=Number.parseInt(nq.get('notif'),10);
  if(Number.isInteger(nidx)&&nidx>=0&&nidx<NOTIF_SCEN.length) setTimeout(()=>runNotifScenario(nidx),900);
}catch(e){}

let storedTheme='system';
try{storedTheme=window.localStorage.getItem('ocx-theme')||'system'}catch(e){}
// 评审便利：?theme=light|dark|system 直接指定主题（仅原型用）。
try{const tq=new URLSearchParams(location.search).get('theme');if(tq&&['light','dark','system'].includes(tq))storedTheme=tq;}catch(e){}
applyTheme(storedTheme);

renderWebdav('unconfigured');
createAnchorTitles();
setRoute(location.hash.slice(1)||'overview',true);
if(currentRoute==='settings') showSettingsSection(parseRouteHash(location.hash).params.get('section')||'general');
renderEnv();
renderTray();
setState('loading');
setTimeout(()=>{
  createAnchorTitles();
  applyHashAnchor(location.hash,true);
},100);
setTimeout(()=>{setEnv('ready');setState('stopped')},800);

// 覆盖式滚动条：滚动时给滚动容器打 .is-scrolling（CSS 里控制滚动条淡入），停止 0.9s 后撤掉。
// scroll 事件不冒泡，用捕获阶段统一接。
window.__scrollQuietTimer=null;
document.addEventListener('scroll',event=>{
  const el=event.target;
  if(!el||el.nodeType!==1) return;
  document.querySelectorAll('.is-scrolling').forEach(node=>{if(node!==el)node.classList.remove('is-scrolling')});
  el.classList.add('is-scrolling');
  clearTimeout(window.__scrollQuietTimer);
  window.__scrollQuietTimer=setTimeout(()=>el.classList.remove('is-scrolling'),900);
},true);


window.addEventListener('prototype:data-paths',event=>{
  const paths=event.detail, oldDefault=DEFAULT_MANAGED_PREFIX;
  MANAGED_PREFIX=paths.prefix;DEFAULT_MANAGED_PREFIX=paths.prefix;MANAGED_ENTRY=paths.entry;
  if(installPath===oldDefault)installPath=paths.prefix;
  runtimeSources.managed.path=paths.entry;
  UNINSTALL_BODY_PLANS.managed.pkg=paths.prefix;UNINSTALL_BODY_PLANS.managed.entry=paths.entry;
  renderRuntimeSource();render();
});
